/**
 * GameHints 组件
 * 
 * 统一管理游戏中所有的提示和状态消息，包括：
 * - 弃牌阶段提示
 * - 手牌弃置交互提示
 * - 对手思考中提示
 * - 响应窗口提示
 */

import React from 'react';
import { useTranslation } from 'react-i18next';
import { Trash2 } from 'lucide-react';
import type { HandDiscardInteractionContract } from './handDiscardInteractionContract';
import type { DiceInteractionContract } from './diceInteractionContract';
import type { InteractionHint } from './interactionPresentationContract';
import { UI_Z_INDEX, HudPortal } from '../../../core';

const dtViewportInlineUnit = (multiplier: number) =>
    `calc(var(--mobile-board-shell-inline-unit, 1vw) * var(--mobile-board-shell-scale, 1) * ${multiplier})`;
const dtViewportBlockUnit = (multiplier: number) =>
    `calc(var(--mobile-board-shell-block-unit, 1vh) * var(--mobile-board-shell-scale, 1) * ${multiplier})`;
const HAND_DISCARD_HINT_TOP_UNITS = 5.6;

export interface GameHintsProps {
    /** 是否处于弃牌模式 */
    isDiscardMode: boolean;
    /** 必须弃牌数量 */
    mustDiscardCount: number;

    /** 手牌弃置的提示、合法候选和动作来自同一交互合同；无此交互时显式传 undefined。 */
    handDiscardInteraction: HandDiscardInteractionContract | undefined;

    /** 当前骰子交互的同一份合同；普通状态显式传 undefined，交互状态不得漏接。 */
    diceInteraction: DiceInteractionContract | undefined;

    /** 是否在等待对手 */
    isWaitingOpponent: boolean;
    /** 对手名称 */
    opponentName: string;

    /** 当前响应提示。卡牌与 Token 响应共用同一个手牌上方提示框。 */
    responsePrompt?: {
        onPass?: () => void;
        kind: 'card' | 'token';
        passLabel?: string;
    };

    /** 是否处于被动重掷选择模式 */
    isPassiveRerollSelecting?: boolean;
}

/**
 * 弃牌阶段提示 Banner
 */
const DiscardHint: React.FC<{ mustDiscardCount: number }> = ({ mustDiscardCount }) => {
    const { t } = useTranslation('game-dicethrone');

    return (
        <div
            className="absolute left-1/2 -translate-x-1/2 pointer-events-none animate-pulse"
            style={{
                zIndex: UI_Z_INDEX.hint,
                bottom: dtViewportInlineUnit(14),
                left: '50%',
                transform: 'translateX(-50%)',
            }}
        >
            <div
                className="rounded-xl bg-gradient-to-r from-red-900/90 to-orange-900/90 border-2 border-red-500/60 backdrop-blur-sm"
                style={{
                    paddingInline: dtViewportInlineUnit(2),
                    paddingBlock: dtViewportInlineUnit(0.8),
                    boxShadow: `0 0 ${dtViewportInlineUnit(2)} rgba(239,68,68,0.4)`,
                }}
            >
                <div className="flex items-center" style={{ gap: dtViewportInlineUnit(1) }}>
                    <Trash2 className="text-red-200" style={{ width: dtViewportInlineUnit(1.5), height: dtViewportInlineUnit(1.5) }} />
                    <div className="flex flex-col">
                        <span className="text-red-200 font-black tracking-wider" style={{ fontSize: dtViewportInlineUnit(1) }}>
                            {t('discard.mustDiscard')}
                        </span>
                        <span className="text-orange-300 font-bold" style={{ fontSize: dtViewportInlineUnit(0.8) }}>
                            {t('discard.selectToDiscard', { count: mustDiscardCount })}
                        </span>
                    </div>
                </div>
            </div>
        </div>
    );
};

const HandDiscardHint: React.FC<{
    interaction: HandDiscardInteractionContract;
}> = ({ interaction }) => {
    const { t } = useTranslation('game-dicethrone');
    const cancelAction = interaction.actions.cancel;

    return (
        <div
            data-testid="dicethrone-hand-discard-hint"
            className="absolute left-1/2 -translate-x-1/2 pointer-events-none"
            style={{
                zIndex: UI_Z_INDEX.hint,
                top: dtViewportInlineUnit(HAND_DISCARD_HINT_TOP_UNITS),
                left: '50%',
                transform: 'translateX(-50%)',
            }}
        >
            <div
                className="flex items-center rounded-xl border-2 border-red-500/60 bg-gradient-to-r from-red-900/95 to-orange-900/95 backdrop-blur-sm"
                style={{
                    gap: dtViewportInlineUnit(1),
                    paddingInline: dtViewportInlineUnit(1.4),
                    paddingBlock: dtViewportInlineUnit(0.7),
                    boxShadow: `0 0 ${dtViewportInlineUnit(2)} rgba(239,68,68,0.4)`,
                }}
            >
                <Trash2 className="shrink-0 text-red-200" style={{ width: dtViewportInlineUnit(1.5), height: dtViewportInlineUnit(1.5) }} />
                <span className="whitespace-nowrap text-red-100 font-black" style={{ fontSize: dtViewportInlineUnit(0.95) }}>
                    {t(interaction.hint.key, interaction.hint.params)}
                </span>
                {cancelAction && (
                    <button
                        type="button"
                        data-testid="dicethrone-hand-discard-cancel"
                        onClick={cancelAction.onActivate}
                        className="pointer-events-auto rounded-lg border border-red-200/70 bg-black/30 px-3 py-2 text-white font-bold hover:bg-black/50"
                        style={{ minHeight: 44, fontSize: dtViewportInlineUnit(0.85) }}
                    >
                        {t(cancelAction.labelKey)}
                    </button>
                )}
            </div>
        </div>
    );
};

/** 普通选骰/改骰提示固定在视口左侧垂直居中。 */
const DiceInteractionHint: React.FC<{ interaction: DiceInteractionContract }> = ({ interaction }) => {
    const { t } = useTranslation('game-dicethrone');

    if (interaction.hint.surface !== 'game-hints') return null;

    return (
        <div
            data-testid="dice-interaction-hint-anchor"
            data-anchor="viewport"
            data-placement="left-center"
            className="fixed left-[max(0.75rem,env(safe-area-inset-left))] top-1/2 -translate-y-1/2 pointer-events-none animate-pulse"
            style={{
                zIndex: UI_Z_INDEX.hint,
                position: 'fixed',
                top: '50%',
                left: 'max(0.75rem, env(safe-area-inset-left))',
                transform: 'translateY(-50%)',
            }}
        >
            <div
                data-testid="dice-interaction-hint"
                className="w-max max-w-[calc(100vw-2rem)] rounded-xl border border-amber-400/60 bg-amber-600/90 text-center shadow-lg backdrop-blur-sm"
                style={{
                    maxWidth: 'min(22rem, calc(100vw - 2rem))',
                    boxSizing: 'border-box',
                    paddingInline: dtViewportInlineUnit(2),
                    paddingBlock: dtViewportInlineUnit(0.6),
                }}
            >
                <span className="text-white font-bold tracking-wide" style={{ fontSize: dtViewportInlineUnit(1) }}>
                    {t(interaction.hint.key, interaction.hint.params)}
                </span>
            </div>
        </div>
    );
};

// 用不可见字符占位，保证宽度稳定，避免点数变化导致布局抖动。
const ThinkingDot: React.FC<{ delayMs: number }> = ({ delayMs }) => (
    <span
        className="inline-block w-[0.6em] text-amber-300/80"
        style={{
            animation: `dicethrone-thinking-dot 1.1s ${delayMs}ms infinite ease-in-out`,
        }}
        aria-hidden="true"
    >
        ·
    </span>
);

/**
 * 对手思考中提示（画面正中央）
 *
 * 之前用整体 pulse 会造成“亮度闪烁”的体感，这里改成省略号动画：
 * - 文案本身保持稳定
 * - 通过 3 个点的逐个淡入淡出表达“正在思考”
 */
const OpponentThinkingHint: React.FC<{ opponentName: string }> = ({ opponentName }) => {
    const { t } = useTranslation('game-dicethrone');

    return (
        <div
            className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none"
            style={{ zIndex: UI_Z_INDEX.overlayRaised }}
        >
            <div className="text-center">
                <div
                    className="text-amber-400 font-bold tracking-wider drop-shadow-[0_0_10px_rgba(251,191,36,0.6)]"
                    style={{ fontSize: dtViewportInlineUnit(2) }}
                >
                    {opponentName}
                </div>

                <div
                    className="text-amber-300/80 font-medium drop-shadow-[0_0_8px_rgba(251,191,36,0.4)]"
                    style={{ fontSize: dtViewportInlineUnit(1.2), marginTop: dtViewportInlineUnit(0.3) }}
                >
                    <span>{t('waiting.thinkingMessage')}</span>
                    <span className="inline-flex items-baseline">
                        <ThinkingDot delayMs={0} />
                        <ThinkingDot delayMs={160} />
                        <ThinkingDot delayMs={320} />
                    </span>
                </div>

                {/* 局部 keyframes：避免引入全局 CSS，且不依赖 Tailwind 配置 */}
                <style>
                    {`
                    @keyframes dicethrone-thinking-dot {
                        0%, 20% { opacity: 0.15; transform: translateY(0); }
                        50% { opacity: 1; transform: translateY(-0.04em); }
                        80%, 100% { opacity: 0.15; transform: translateY(0); }
                    }
                    `}
                </style>
            </div>
        </div>
    );
};

/**
 * 响应窗口：当前玩家可响应
 */
const ResponseWindowHint: React.FC<{
    onResponsePass?: () => void;
    kind: 'card' | 'token';
    passLabel?: string;
    hint?: InteractionHint;
}> = ({ onResponsePass, kind, passLabel, hint }) => {
    const { t } = useTranslation('game-dicethrone');

    const handleClick = React.useCallback((event: React.MouseEvent<HTMLButtonElement>) => {
        event.stopPropagation();
        if (!onResponsePass) return;
        onResponsePass();
    }, [onResponsePass]);

    return (
        <div
            data-testid="dicethrone-response-window-hint"
            data-response-kind={kind}
            data-anchor="viewport"
            data-placement="fixed-hand-lift-slot"
            className="fixed left-1/2 -translate-x-1/2"
            style={{
                zIndex: UI_Z_INDEX.hint,
                position: 'fixed',
                bottom: `clamp(10rem, ${dtViewportBlockUnit(42)}, 26rem)`,
                left: '50%',
                transform: 'translateX(-50%)',
                pointerEvents: onResponsePass ? 'auto' : 'none',
            }}
        >
            <div
                className="relative rounded-full"
            >
                <div
                    aria-hidden="true"
                    data-testid="dicethrone-response-orbit"
                    className="pointer-events-none absolute -inset-[4px] overflow-hidden rounded-full"
                >
                <div
                        data-testid="dicethrone-response-orbit-track"
                        className="absolute left-1/2 top-1/2 h-[520%] w-[520%]"
                        style={{
                            background: 'conic-gradient(from 0deg, transparent 0deg 300deg, rgba(255,214,77,0.28) 306deg, #fffbe0 320deg, #ffd65f 336deg, rgba(255,214,77,0.24) 350deg, transparent 360deg)',
                            transform: 'translate(-50%, -50%)',
                            animation: 'dicethrone-response-border-orbit 1.2s linear infinite',
                        }}
                    />
                </div>
                <div
                    data-testid="dicethrone-response-window-hint-panel"
                    className="relative z-10 flex items-center rounded-full border border-[#ffe16d] bg-[#2b1837]"
                    style={{
                        border: '1.5px solid rgba(255,225,109,0.9)',
                        borderRadius: '9999px',
                        backgroundColor: '#2b1837',
                        boxShadow: 'none',
                        gap: dtViewportInlineUnit(0.9),
                        paddingInline: dtViewportInlineUnit(1.15),
                        paddingBlock: dtViewportInlineUnit(0.62),
                    }}
                >
                    <style>{`
                        @keyframes dicethrone-response-border-orbit {
                            from { transform: translate(-50%, -50%) rotate(0deg); }
                            to { transform: translate(-50%, -50%) rotate(360deg); }
                        }
                        @media (prefers-reduced-motion: reduce) {
                            [data-testid="dicethrone-response-orbit-track"] { animation: none !important; }
                        }
                    `}</style>
                    <span
                        className="relative z-10 text-[#fff3bd] font-black tracking-wider"
                        style={{ fontSize: dtViewportInlineUnit(0.95) }}
                    >
                        {t(hint?.key ?? 'response.yourTurn', hint?.params)}
                    </span>
                    {onResponsePass && (
                        <button
                            type="button"
                            data-testid="dicethrone-response-pass-button"
                            data-tutorial-id="response-pass-button"
                            onClick={handleClick}
                            className="relative z-10 min-h-[44px] rounded-lg border-2 border-[#fff0ae] bg-[#9b7118] font-black tracking-wider text-white transition-[background-color] duration-150 hover:bg-[#b88720] active:bg-[#865f14]"
                            style={{
                                minHeight: 44,
                                border: '2px solid #fff0ae',
                                borderRadius: '0.5rem',
                                backgroundColor: '#9b7118',
                                boxShadow: 'none',
                                pointerEvents: 'auto',
                                paddingInline: dtViewportInlineUnit(1),
                                fontSize: dtViewportInlineUnit(0.78),
                            }}
                        >
                            {passLabel ?? t('response.pass')}
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

/**
 * 被动重掷选择提示
 */
const PassiveRerollHint: React.FC = () => {
    const { t } = useTranslation('game-dicethrone');

    return (
        <div
            className="absolute left-1/2 -translate-x-1/2 pointer-events-none animate-pulse"
            style={{ zIndex: UI_Z_INDEX.hint, top: dtViewportInlineUnit(6) }}
        >
            <div
                className="bg-emerald-600/90 backdrop-blur-sm rounded-xl border border-emerald-400/60 shadow-lg text-center"
                style={{ paddingInline: dtViewportInlineUnit(2), paddingBlock: dtViewportInlineUnit(0.6) }}
            >
                <span className="text-white font-bold tracking-wide" style={{ fontSize: dtViewportInlineUnit(1) }}>
                    {t('passive.selectDieHint')}
                </span>
            </div>
        </div>
    );
};

/**
 * 游戏提示统一管理组件
 */
export const GameHints: React.FC<GameHintsProps> = ({
    isDiscardMode,
    mustDiscardCount,
    handDiscardInteraction,
    diceInteraction,
    isWaitingOpponent,
    opponentName,
    responsePrompt,
    isPassiveRerollSelecting,
}) => {
    const tokenResponseSettlement = diceInteraction?.kind === 'tokenResponseSettlement'
        ? diceInteraction
        : undefined;
    const visibleResponsePrompt = responsePrompt ?? (tokenResponseSettlement
        ? { kind: tokenResponseSettlement.responseKind, onPass: undefined, passLabel: undefined }
        : undefined);

    return (
        <HudPortal>
            {/* 弃牌阶段提示 Banner */}
            {isDiscardMode && (
                <DiscardHint mustDiscardCount={mustDiscardCount} />
            )}

            {handDiscardInteraction && (
                <HandDiscardHint
                    interaction={handDiscardInteraction}
                />
            )}

            {diceInteraction && <DiceInteractionHint interaction={diceInteraction} />}

            {/* 被动重掷选择提示 */}
            {isPassiveRerollSelecting && (
                <PassiveRerollHint />
            )}

            {/* 对手思考中提示（画面正中央，无背景，缓慢闪烁） */}
            {isWaitingOpponent && (
                <OpponentThinkingHint opponentName={opponentName} />
            )}

            {/* 响应窗口：当前玩家可响应 */}
            {visibleResponsePrompt && (
                <ResponseWindowHint
                    onResponsePass={visibleResponsePrompt.onPass}
                    kind={visibleResponsePrompt.kind}
                    passLabel={visibleResponsePrompt.passLabel}
                    hint={tokenResponseSettlement?.hint}
                />
            )}
        </HudPortal>
    );
};

/**
 * 状态选择交互覆盖层
 * 用于状态效果选择、玩家选择等交互
 * 
 * 已适配新的 InteractionSystem（从 sys.interaction.current 读取）
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { Check, Search, X } from 'lucide-react';
import type { AbilityCard, InteractionDescriptor, HeroState } from '../domain/types';
import type { TokenDef } from '../domain/tokenTypes';
import type { PlayerId } from '../../../engine/types';
import { UI_Z_INDEX } from '../../../core';
import { CardPreview } from '../../../components/common/media/CardPreview';
import { SelectableEffectsContainer, type StatusAtlases } from './statusEffects';
import { GameModal } from './components/GameModal';
import { GameButton } from './components/GameButton';
import { getDiceThroneCardPreviewRef } from './cardPreviewHelper';
import { buildBoardShellInlineUnitValue } from '../../../shared/runtimeLayoutUnits';
import { DICETHRONE_HAND_AREA_HEIGHT_UNITS } from './handLayoutConstants';

type TeamTone = 'self' | 'ally' | 'enemy';

const CARD_POOL_CARD_WIDTH = 'clamp(88px, min(7.2vw, 12.5vh), 132px)';
const CARD_POOL_FOCUSED_CARD_WIDTH = 'clamp(104px, min(14vw, 23vh), 188px)';
const CARD_POOL_CARD_MAX_WIDTH_PX = 132;
const CARD_POOL_PANEL_MAX_WIDTH_PX = 1120;
const CARD_POOL_PANEL_SAFE_PADDING_PX = 96;
const CARD_POOL_GRID_GAP_PX = 16;

const normalizeCardPoolSearchText = (value: unknown): string => (
    String(value ?? '')
        .normalize('NFKC')
        .trim()
        .toLocaleLowerCase()
);

const getCardPoolViewportWidth = (): number => {
    if (typeof window === 'undefined') return 1024;
    return Math.max(320, window.innerWidth);
};

const getCardPoolSingleRowCapacity = (): number => {
    const viewportWidth = getCardPoolViewportWidth();
    const panelWidth = Math.min(CARD_POOL_PANEL_MAX_WIDTH_PX, viewportWidth - 32);
    const usableWidth = Math.max(CARD_POOL_CARD_MAX_WIDTH_PX, panelWidth - CARD_POOL_PANEL_SAFE_PADDING_PX);
    return Math.max(1, Math.floor((usableWidth + CARD_POOL_GRID_GAP_PX) / (CARD_POOL_CARD_MAX_WIDTH_PX + CARD_POOL_GRID_GAP_PX)));
};

interface ToneClasses {
    idleBorderClassName: string;
    passiveBorderClassName: string;
    titleClassName: string;
    badgeClassName: string;
}

const PlayerCardShell = ({
    testId,
    playerId,
    teamTone,
    titleClassName,
    badgeClassName,
    displayName,
    relationLabel,
    seatLabel,
    containerClassName,
    onClick,
    locked,
    selected,
    footer,
    children,
}: {
    testId: string;
    playerId: PlayerId;
    teamTone: TeamTone;
    titleClassName: string;
    badgeClassName: string;
    displayName: string;
    relationLabel: string;
    seatLabel: string;
    containerClassName: string;
    onClick?: () => void;
    locked?: boolean;
    selected?: boolean;
    footer?: React.ReactNode;
    children: React.ReactNode;
}) => (
    <div
        onClick={onClick}
        data-testid={testId}
        data-player-id={playerId}
        data-team-tone={teamTone}
        data-locked={locked ? 'true' : 'false'}
        data-selected={selected ? 'true' : 'false'}
        className={containerClassName}
    >
        <div className="mb-3 flex items-start justify-between gap-3">
            <div className="min-w-0">
                <div className={`font-bold text-lg leading-tight ${titleClassName}`}>
                    {displayName}
                </div>
                <div className="mt-1 text-xs uppercase tracking-[0.18em] text-slate-400">
                    {relationLabel}
                </div>
            </div>
            <div className={`rounded-full border px-2 py-1 text-xs font-semibold uppercase tracking-[0.18em] ${badgeClassName}`}>
                {seatLabel}
            </div>
        </div>
        {children}
        {footer ? (
            <div className="mt-3 text-center text-xs font-semibold tracking-[0.18em] uppercase text-slate-300/85">
                {footer}
            </div>
        ) : null}
    </div>
);

export interface InteractionOverlayProps {
    /** 当前交互（从 sys.interaction.current 获取） */
    interaction: InteractionDescriptor;
    /** 所有玩家状态 */
    players: Record<PlayerId, HeroState>;
    /** 状态 / token 定义，用于过滤不可移除效果 */
    tokenDefinitions?: TokenDef[];
    /** 当前玩家 ID */
    currentPlayerId: PlayerId;
    /** 玩家显示名 */
    playerNames?: Record<PlayerId, string>;
    /** 当前 4 人站位顺序 */
    seatingOrder?: PlayerId[];
    /** 队伍映射（4 人 / 2v2 用于区分友敌） */
    teamIdByPlayerId?: Record<PlayerId, string>;
    /** 选择状态效果回调 */
    onSelectStatus: (playerId: PlayerId, statusId: string) => void;
    /** 选择玩家回调 */
    onSelectPlayer: (playerId: PlayerId) => void;
    /** 选择手牌回调 */
    onSelectHandCard?: (cardId: string) => void;
    /** 确认交互 */
    onConfirm: () => void;
    /** 取消交互 */
    onCancel: () => void;
    /** 状态图标图集 */
    statusIconAtlas?: StatusAtlases | null;
    /** 语言 */
    locale?: string;
    /** 保留提示确认能力，同时允许查看/操作背景棋盘。 */
    allowBackgroundInteraction?: boolean;
    /** 限制是否可提交；复用选择界面承载 ChoiceRequest 时对应原交互权限。 */
    canResolve?: boolean;
    /** 操作按钮翻译 key 覆盖，用于选择器内明确显示“清空选择”或“跳过”。 */
    cancelLabelKey?: string;
    confirmLabelKey?: string;
    /** 是否允许清空当前本地选择。 */
    canCancel?: boolean;
}

export const InteractionOverlay: React.FC<InteractionOverlayProps> = ({
    interaction,
    players,
    tokenDefinitions,
    currentPlayerId,
    playerNames,
    seatingOrder,
    teamIdByPlayerId,
    onSelectStatus,
    onSelectPlayer,
    onSelectHandCard = () => undefined,
    onConfirm,
    onCancel,
    statusIconAtlas,
    locale,
    allowBackgroundInteraction = false,
    canResolve = true,
    cancelLabelKey = 'common.cancel',
    confirmLabelKey = 'common.confirm',
    canCancel = true,
}) => {
    const { t, i18n } = useTranslation('game-dicethrone');
    const interactionType = interaction.type;
    const selectedItems = interaction.selected ?? [];
    const targetPlayerIds = interaction.targetPlayerIds ?? Object.keys(players);
    const isStatusSelection = interactionType === 'selectStatus' || interactionType === 'selectTargetStatus';
    const isTransferStatusSelection = (
        (interactionType === 'selectStatus' || interactionType === 'selectTargetStatus')
        && interaction.transferConfig !== undefined
        && !interaction.transferConfig.statusId
    );
    const isRemovableEffect = React.useCallback((effectId: string) => {
        const definition = tokenDefinitions?.find(def => def.id === effectId);
        return definition?.passiveTrigger?.removable ?? true;
    }, [tokenDefinitions]);
    const getRemovableEntries = React.useCallback((entries: Record<string, number> | undefined) => {
        return Object.fromEntries(
            Object.entries(entries ?? {}).filter(([effectId, stacks]) => (
                stacks > 0
                && isRemovableEffect(effectId)
                && (!isTransferStatusSelection
                    || tokenDefinitions?.find(definition => definition.id === effectId)?.passiveTrigger?.transferable !== false)
            )),
        );
    }, [isRemovableEffect, isTransferStatusSelection, tokenDefinitions]);
    const getStatusEntries = React.useCallback((
        playerId: PlayerId,
        collection: 'statusEffects' | 'tokens',
        entries: Record<string, number> | undefined,
    ) => {
        const candidates = interaction.candidateStatusOptions;
        if (!candidates) return getRemovableEntries(entries);
        const allowedIds = new Set(candidates
            .filter(candidate => candidate.playerId === playerId && candidate.collection === collection)
            .map(candidate => candidate.statusId));
        return Object.fromEntries(Object.entries(entries ?? {}).filter(([statusId, stacks]) => (
            stacks > 0 && allowedIds.has(statusId)
        )));
    }, [getRemovableEntries, interaction.candidateStatusOptions]);

    // 状态效果选择模式
    // 玩家选择模式（选择目标玩家：授予 token / 移除所有状态等）
    const isPlayerSelection = interactionType === 'selectPlayer';
    // 卡牌选择模式（由持有者从手牌或抽牌堆自行选择）
    const isHandCardSelection = interactionType === 'selectHandCard';
    const isDeckCardSelection = interactionType === 'selectDeckCard';
    const isCardSelection = isHandCardSelection || isDeckCardSelection || interactionType === 'selectCard';
    const cardSourceZone = interaction.cardSourceZone ?? (isDeckCardSelection ? 'deck' : 'hand');
    // 转移模式的第二阶段：选择目标玩家
    const isTransferTargetSelection = interactionType === 'selectTargetStatus' && interaction.transferConfig?.statusId;
    const shouldRenderStatusOwners = isStatusSelection && !isTransferTargetSelection;

    // 获取已选择的状态信息（用于显示）
    const selectedStatusId = isStatusSelection ? selectedItems[0] : undefined;

    // 是否要求目标已有状态（如"移除所有状态"），默认不要求
    const requiresTargetWithStatus = interaction.requiresTargetWithStatus ?? false;

    // 检查是否有任何玩家有可移除的状态
    const playersWithStatus = targetPlayerIds.filter(pid => {
        const p = players[pid];
        if (!p) return false;
        const hasEffects = Object.keys(getStatusEntries(pid, 'statusEffects', p.statusEffects)).length > 0;
        const hasTokens = Object.keys(getStatusEntries(pid, 'tokens', p.tokens)).length > 0;
        return hasEffects || hasTokens;
    });

    const currentTeamId = teamIdByPlayerId?.[currentPlayerId];
    const fallbackSeatOrder = React.useMemo(() => Object.keys(players) as PlayerId[], [players]);
    const resolvedSeatingOrder = seatingOrder && seatingOrder.length > 0 ? seatingOrder : fallbackSeatOrder;

    const getPlayerMeta = React.useCallback((pid: PlayerId) => {
        const isSelf = pid === currentPlayerId;
        const isAlly = !isSelf && !!currentTeamId && teamIdByPlayerId?.[pid] === currentTeamId;
        const teamTone: TeamTone = isSelf ? 'self' : isAlly ? 'ally' : 'enemy';
        const seatIndex = resolvedSeatingOrder.indexOf(pid);
        const seatNumber = seatIndex >= 0 ? seatIndex + 1 : Number.parseInt(String(pid), 10) + 1;
        const seatLabel = Number.isFinite(seatNumber) ? `P${seatNumber}` : `P${String(pid)}`;
        const displayName = playerNames?.[pid] || (isSelf ? t('common.self') : t('common.opponent'));
        const relationLabel = isSelf ? t('common.self') : isAlly ? t('common.ally') : t('common.enemy');
        return { isSelf, isAlly, teamTone, seatLabel, displayName, relationLabel };
    }, [currentPlayerId, currentTeamId, playerNames, resolvedSeatingOrder, t, teamIdByPlayerId]);

    const getToneClasses = React.useCallback((teamTone: TeamTone): ToneClasses => {
        if (teamTone === 'self') {
            return {
                idleBorderClassName: 'border-cyan-500/60 bg-cyan-950/20 hover:border-cyan-400',
                passiveBorderClassName: 'border-cyan-500/60 bg-cyan-950/20',
                titleClassName: 'text-cyan-300',
                badgeClassName: 'border-cyan-400/60 text-cyan-200 bg-cyan-950/50',
            };
        }
        if (teamTone === 'ally') {
            return {
                idleBorderClassName: 'border-emerald-500/60 bg-emerald-950/20 hover:border-emerald-400',
                passiveBorderClassName: 'border-emerald-500/60 bg-emerald-950/20',
                titleClassName: 'text-emerald-300',
                badgeClassName: 'border-emerald-400/60 text-emerald-200 bg-emerald-950/50',
            };
        }
        return {
            idleBorderClassName: 'border-rose-500/60 bg-slate-800/50 hover:border-rose-400',
            passiveBorderClassName: 'border-rose-500/60 bg-slate-800/50',
            titleClassName: 'text-rose-300',
            badgeClassName: 'border-rose-400/60 text-rose-200 bg-rose-950/50',
        };
    }, []);

    const transferSourceCard = React.useMemo(() => {
        if (!isTransferTargetSelection) return null;
        const sourcePlayerId = interaction.transferConfig?.sourcePlayerId;
        const statusId = interaction.transferConfig?.statusId;
        if (!sourcePlayerId || !statusId) return null;

        const sourcePlayer = players[sourcePlayerId];
        if (!sourcePlayer) return null;

        const effectStacks = sourcePlayer.statusEffects?.[statusId] ?? 0;
        const tokenStacks = sourcePlayer.tokens?.[statusId] ?? 0;
        return {
            playerId: sourcePlayerId,
            statusId,
            characterId: sourcePlayer.characterId,
            effects: effectStacks > 0 ? { [statusId]: effectStacks } : {},
            tokens: tokenStacks > 0 ? { [statusId]: tokenStacks } : {},
        };
    }, [interaction.transferConfig?.sourcePlayerId, interaction.transferConfig?.statusId, isTransferTargetSelection, players]);

    const minSelectCount = interaction.minSelectCount ?? (
        isPlayerSelection || isCardSelection || isTransferTargetSelection ? 1 : interaction.selectCount
    );
    const canConfirm = canResolve && selectedItems.length >= minSelectCount;
    const [cardPoolSearch, setCardPoolSearch] = React.useState('');
    const cardSelectionCards = React.useMemo(() => {
        if (!isCardSelection) return [] as AbilityCard[];
        const player = players[interaction.playerId];
        const sourceCards = player?.[cardSourceZone] ?? [];
        const candidateIds = interaction.candidateCardIds;
        return candidateIds ? sourceCards.filter(card => candidateIds.includes(card.id)) : sourceCards;
    }, [cardSourceZone, interaction.candidateCardIds, interaction.playerId, isCardSelection, players]);
    const cardPoolSearchSignature = React.useMemo(() => (
        [
            interaction.id,
            interaction.playerId,
            interactionType,
            cardSourceZone,
            cardSelectionCards.map(card => card.id).join('|'),
        ].join('::')
    ), [cardSelectionCards, cardSourceZone, interaction.id, interaction.playerId, interactionType]);

    React.useEffect(() => {
        setCardPoolSearch('');
    }, [cardPoolSearchSignature]);

    const resolveCardName = React.useCallback((card: AbilityCard): string => {
        const rawCardName = card.i18n?.[locale ?? 'zh-CN']?.name
            ?? card.i18n?.['zh-CN']?.name
            ?? card.name
            ?? card.id;
        if (
            typeof rawCardName === 'string'
            && rawCardName.startsWith('cards.')
            && i18n.exists(rawCardName, { ns: 'game-dicethrone' })
        ) {
            return t(rawCardName);
        }
        return String(rawCardName);
    }, [i18n, locale, t]);

    const normalizedCardPoolSearch = normalizeCardPoolSearchText(cardPoolSearch);
    const shouldShowCardPoolSearch = cardSelectionCards.length > getCardPoolSingleRowCapacity();
    const visibleCardSelectionCards = React.useMemo(() => {
        if (!shouldShowCardPoolSearch || normalizedCardPoolSearch.length === 0) {
            return cardSelectionCards;
        }

        return cardSelectionCards.filter((card) => {
            const localizedNames = Object.values(card.i18n ?? {})
                .flatMap(entry => [entry.name, entry.description]);
            const haystack = [
                resolveCardName(card),
                card.name,
                card.description,
                card.id,
                card.type,
                card.timing,
                card.cpCost,
                ...localizedNames,
            ].map(normalizeCardPoolSearchText).join(' ');
            return haystack.includes(normalizedCardPoolSearch);
        });
    }, [cardSelectionCards, normalizedCardPoolSearch, resolveCardName, shouldShowCardPoolSearch]);

    // Derived presence
    const isOpen = true; // Controlled by BoardOverlays

    if (isCardSelection) {
        const useFocusedCardSize = cardSelectionCards.length <= 6;
        const hasFocusedSingleCardSelection = useFocusedCardSize
            && (interaction.selectCount ?? 1) <= 1
            && selectedItems.length > 0;
        const cardPoolCardStyle: React.CSSProperties = {
            backgroundColor: '#0f172a',
            borderRadius: '0.25rem',
            width: useFocusedCardSize ? CARD_POOL_FOCUSED_CARD_WIDTH : CARD_POOL_CARD_WIDTH,
        };

        return (
            <div
                data-testid="dt-card-pool-overlay"
                data-card-pool-layout="center-stage"
                data-card-pool-hand-protection="shared-stage-visible-hand"
                data-card-pool-browse-mode="grid-scroll"
                className="fixed inset-0 pointer-events-none"
                style={{ zIndex: UI_Z_INDEX.overlay }}
                onClick={(e) => e.stopPropagation()}
            >
                <div
                    data-testid="dt-card-pool-panel"
                    className="pointer-events-auto absolute inset-x-0 bottom-[max(0.75rem,env(safe-area-inset-bottom))] top-[clamp(4.25rem,9vh,6.25rem)] min-h-0 px-4"
                    onClick={(e) => e.stopPropagation()}
                    onMouseDown={(e) => e.nativeEvent.stopImmediatePropagation()}
                >
                    <div
                        data-testid="dt-card-pool-surface"
                        className="relative isolate mx-auto flex h-full min-h-0 w-full max-w-[70rem] flex-col px-3 py-3"
                    >
                        <div
                            aria-hidden="true"
                            data-testid="dt-card-pool-backdrop"
                            data-card-pool-hand-clearance="hand-area-top"
                            className="pointer-events-none absolute inset-x-[2%] top-0 -z-10 border-y border-red-300/20 bg-[linear-gradient(90deg,transparent_0%,rgba(10,3,7,0.82)_12%,rgba(24,4,11,0.94)_50%,rgba(10,3,7,0.82)_88%,transparent_100%)] shadow-[0_18px_42px_rgba(0,0,0,0.34)] backdrop-blur-[1px]"
                            style={{ bottom: buildBoardShellInlineUnitValue(DICETHRONE_HAND_AREA_HEIGHT_UNITS) }}
                        />
                        <h2
                            data-testid="dt-card-pool-title"
                            className="mb-2 shrink-0 text-center text-base font-black uppercase tracking-[0.12em] text-amber-100 drop-shadow-[0_2px_9px_rgba(127,29,29,0.78)] sm:text-lg"
                        >
                            {t(interaction.titleKey, { count: interaction.selectCount })}
                        </h2>
                        {shouldShowCardPoolSearch ? (
                            <div
                                data-testid="dt-card-pool-search"
                                className="mx-auto mb-1 max-w-[min(100%,30rem)]"
                            >
                                <div className="relative">
                                    <span
                                        data-testid="dt-card-pool-search-leading-icon"
                                        className="pointer-events-none absolute inset-y-0 left-3 flex items-center text-red-100/70"
                                    >
                                        <Search className="h-4 w-4" strokeWidth={2.1} />
                                    </span>
                                    <input
                                        type="search"
                                        value={cardPoolSearch}
                                        onChange={(event) => setCardPoolSearch(event.target.value)}
                                        placeholder={t('interaction.cardPoolSearchPlaceholder')}
                                        data-testid="dt-card-pool-search-input"
                                        className="h-9 w-full rounded-full border border-red-200/25 bg-[#1a0509]/72 pl-10 pr-10 text-sm font-bold text-amber-50 outline-none placeholder:text-red-100/38 focus:border-red-200/60 focus:ring-2 focus:ring-red-300/20"
                                    />
                                    {normalizedCardPoolSearch.length > 0 ? (
                                        <button
                                            type="button"
                                            onClick={() => setCardPoolSearch('')}
                                            data-testid="dt-card-pool-search-clear"
                                            className="absolute right-1.5 top-1/2 flex h-7 w-7 -translate-y-1/2 items-center justify-center rounded-full bg-red-100/10 text-amber-50 transition-colors hover:bg-red-100/20 focus:outline-none focus-visible:ring-2 focus-visible:ring-red-200"
                                            aria-label={t('interaction.cardPoolSearchClear')}
                                        >
                                            <X size={14} strokeWidth={2.2} />
                                        </button>
                                    ) : null}
                                </div>
                                <div
                                    data-testid="dt-card-pool-result-count"
                                    className="mt-1.5 text-center text-[11px] font-bold tracking-[0.08em] text-amber-100/68"
                                >
                                    {t('interaction.cardPoolFilterResultCount', {
                                        visible: visibleCardSelectionCards.length,
                                        total: cardSelectionCards.length,
                                    })}
                                </div>
                            </div>
                        ) : null}
                        <div
                            data-testid="dt-card-pool-selection"
                            data-card-pool-kind={cardSourceZone}
                            data-card-pool-visible-rows="two"
                            className="scrollbar-thin mx-auto min-h-0 max-h-[min(50vh,28rem)] w-full overflow-y-auto overflow-x-hidden px-1 py-3 [scrollbar-color:rgba(248,113,113,0.42)_transparent]"
                        >
                            <div
                                data-testid="dt-card-pool-track"
                                className="mx-auto flex min-w-full flex-wrap items-start justify-center gap-[clamp(0.65rem,1vw,1rem)] px-3"
                            >
                                {visibleCardSelectionCards.length === 0 ? (
                                    <div
                                        data-testid="dt-card-pool-empty"
                                        className="flex min-h-[9rem] min-w-[min(22rem,76vw)] items-center justify-center rounded-[0.35rem] border border-dashed border-red-200/22 bg-[#120407]/58 px-6 text-center text-sm font-bold tracking-[0.08em] text-amber-100/72"
                                    >
                                        {t('interaction.cardPoolSearchEmpty')}
                                    </div>
                                ) : visibleCardSelectionCards.map(card => {
                                    const ownerCharacterId = players[interaction.playerId]?.characterId;
                                    const previewRef = card.previewRef ?? getDiceThroneCardPreviewRef(card.id, ownerCharacterId);
                                    const cardName = resolveCardName(card);
                                    const isSelected = selectedItems.includes(card.id);
                                    return (
                                        <button
                                            key={card.id}
                                            type="button"
                                            data-testid={`dt-${cardSourceZone}-card-option-${card.id}`}
                                            data-selected={isSelected ? 'true' : 'false'}
                                            data-card-pool-mode="preview"
                                            data-card-preview-ready={previewRef ? 'true' : 'false'}
                                            data-selection-focus={isSelected
                                                ? 'selected'
                                                : hasFocusedSingleCardSelection ? 'deemphasized' : 'available'}
                                            aria-label={`${cardName} ${card.type} ${card.cpCost} CP`}
                                            aria-pressed={isSelected}
                                            onClick={() => onSelectHandCard(card.id)}
                                            className={`
                                                group relative flex flex-shrink-0 cursor-pointer flex-col items-center border-0 bg-transparent p-0 text-left transition-[transform,opacity] duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-red-200
                                                ${isSelected
                                                    ? 'z-10'
                                                    : hasFocusedSingleCardSelection
                                                        ? 'opacity-75 hover:-translate-y-1 hover:scale-[1.02] hover:opacity-100 hover:z-10'
                                                        : 'hover:-translate-y-1 hover:scale-[1.02] hover:z-10'}
                                            `}
                                        >
                                            <div
                                                data-testid={`dt-card-choice-preview-${card.id}`}
                                                className={`
                                                    overflow-hidden rounded-[0.3rem] transition-[box-shadow,filter] duration-200
                                                    ${isSelected
                                                        ? 'ring-[3px] ring-amber-200 shadow-[0_0_0_2px_rgba(127,29,29,0.96),0_0_28px_rgba(251,191,36,0.72),0_18px_28px_rgba(0,0,0,0.58)]'
                                                        : 'shadow-[0_12px_22px_rgba(0,0,0,0.42)] group-hover:ring-1 group-hover:ring-red-200/75 group-hover:shadow-[0_0_16px_rgba(185,28,28,0.42),0_14px_24px_rgba(0,0,0,0.46)]'}
                                                `}
                                            >
                                                <CardPreview
                                                    previewRef={previewRef}
                                                    locale={locale}
                                                    className="rounded-[0.3rem] bg-[#150609]"
                                                    style={cardPoolCardStyle}
                                                    alt={cardName}
                                                />
                                            </div>
                                            {isSelected && (
                                                <span
                                                    aria-hidden="true"
                                                    data-testid={`dt-card-choice-selected-${card.id}`}
                                                    className="absolute -right-2 -top-2 z-20 grid h-8 w-8 place-items-center rounded-full border-[3px] border-[#2b0808] bg-amber-300 text-[#321010] shadow-[0_0_0_2px_rgba(255,244,214,0.9),0_4px_12px_rgba(0,0,0,0.6)]"
                                                >
                                                    <Check size={18} strokeWidth={3} />
                                                </span>
                                            )}
                                        </button>
                                    );
                                })}
                            </div>
                        </div>
                        <div
                            data-testid="dt-card-pool-actions"
                            className="mt-2 flex shrink-0 items-center justify-center gap-3"
                        >
                            {canCancel && (
                                <GameButton
                                    onClick={onCancel}
                                    variant="secondary"
                                    size="sm"
                                    data-testid="dt-interaction-clear"
                                >
                                    {t(cancelLabelKey)}
                                </GameButton>
                            )}
                            <GameButton
                                onClick={onConfirm}
                                disabled={!canConfirm}
                                variant="primary"
                                size="sm"
                                data-testid="dt-interaction-confirm"
                            >
                                {t(confirmLabelKey)}
                            </GameButton>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <GameModal
            isOpen={isOpen}
            title={
                <div>
                    <div>{t(interaction.titleKey, { count: interaction.selectCount })}</div>
                    {interaction.transferConfig?.statusId && (
                        <div className="text-slate-400 text-sm mt-1 font-normal normal-case">
                            {t('interaction.transferSelectTarget')}
                        </div>
                    )}
                </div>
            }
            width="xl"
            closeOnBackdrop={false} // Force interaction
            allowBackgroundInteraction={allowBackgroundInteraction}
            footer={
                <>
                    {canCancel && (
                        <GameButton
                            onClick={onCancel}
                            variant="secondary"
                            className="px-8 -translate-y-0.5 shadow-[0_6px_0_#334155] active:translate-y-[3px] active:shadow-[0_2px_0_#334155]"
                            data-testid="dt-interaction-clear"
                        >
                            {t(cancelLabelKey)}
                        </GameButton>
                    )}
                    <GameButton
                        onClick={onConfirm}
                        disabled={!canConfirm}
                        variant="primary"
                        className="px-8 -translate-y-0.5 shadow-[0_6px_0_#b45309] active:translate-y-[3px] active:shadow-[0_2px_0_#b45309]"
                        data-testid="dt-interaction-confirm"
                    >
                        {t(confirmLabelKey)}
                    </GameButton>
                </>
            }
        >
            <div className="flex flex-col w-full p-2">
                {/* 玩家选择区域 */}
                {(shouldRenderStatusOwners || isPlayerSelection) && (
                    <div className="flex flex-wrap gap-4 justify-center">
                        {targetPlayerIds.map(pid => {
                            const player = players[pid];
                            if (!player) return null;

                            const { teamTone, seatLabel, displayName, relationLabel } = getPlayerMeta(pid);
                            const { idleBorderClassName, passiveBorderClassName, titleClassName, badgeClassName } = getToneClasses(teamTone);
                            const hasStatus = playersWithStatus.includes(pid);
                            const isSelected = selectedItems.includes(pid);

                            // 玩家选择模式
                            if (isPlayerSelection) {
                                // 不要求目标有状态时，所有玩家都可选
                                const canSelect = requiresTargetWithStatus ? hasStatus : true;
                                return (
                                    <PlayerCardShell
                                        key={pid}
                                        testId={`dt-player-target-${pid}`}
                                        playerId={pid}
                                        teamTone={teamTone}
                                        titleClassName={titleClassName}
                                        badgeClassName={badgeClassName}
                                        displayName={displayName}
                                        relationLabel={relationLabel}
                                        seatLabel={seatLabel}
                                        onClick={canSelect ? () => onSelectPlayer(pid) : undefined}
                                        selected={isSelected}
                                        containerClassName={`
                                            p-4 rounded-xl border-2 transition-all duration-200 min-w-[200px]
                                            ${canSelect ? 'cursor-pointer hover:scale-[1.03]' : 'opacity-50 cursor-not-allowed'}
                                            ${isSelected
                                                ? 'border-amber-400 bg-amber-950/30 ring-2 ring-amber-300/80'
                                                : canSelect
                                                    ? idleBorderClassName
                                                    : 'border-slate-700 bg-slate-800/30'}
                                        `}
                                    >
                                        {/* 显示玩家的状态效果（仅供参考） */}
                                        <SelectableEffectsContainer
                                            effects={requiresTargetWithStatus ? getStatusEntries(pid, 'statusEffects', player.statusEffects) : (player.statusEffects ?? {})}
                                            tokens={requiresTargetWithStatus ? getStatusEntries(pid, 'tokens', player.tokens) : player.tokens}
                                            highlightAll={false}
                                            getItemTestId={(statusId) => `dt-status-effect-${pid}-${statusId}`}
                                            size="small"
                                            className="justify-center"
                                            locale={locale}
                                            atlas={statusIconAtlas}
                                            characterId={player.characterId}
                                        />
                                        {!hasStatus && requiresTargetWithStatus && (
                                            <div className="text-slate-500 text-sm text-center mt-2">
                                                {t('interaction.noStatus')}
                                            </div>
                                        )}
                                    </PlayerCardShell>
                                );
                            }

                            // 状态效果选择模式
                            return (
                                <PlayerCardShell
                                    key={pid}
                                    testId={`dt-status-owner-${pid}`}
                                    playerId={pid}
                                    teamTone={teamTone}
                                    titleClassName={titleClassName}
                                    badgeClassName={badgeClassName}
                                    displayName={displayName}
                                    relationLabel={relationLabel}
                                    seatLabel={seatLabel}
                                    containerClassName={`
                                        p-4 rounded-xl border-2 transition-all duration-200 min-w-[200px]
                                        ${hasStatus
                                            ? passiveBorderClassName
                                            : 'border-slate-700 bg-slate-800/30 opacity-50'}
                                    `}
                                >
                                    {hasStatus ? (
                                        <SelectableEffectsContainer
                                            effects={getStatusEntries(pid, 'statusEffects', player.statusEffects)}
                                            tokens={getStatusEntries(pid, 'tokens', player.tokens)}
                                            selectedId={interaction.selectedStatusPlayerId === pid ? selectedStatusId : undefined}
                                            highlightAll={true}
                                            onSelectEffect={(statusId) => onSelectStatus(pid, statusId)}
                                            getItemTestId={(statusId) => `dt-status-effect-${pid}-${statusId}`}
                                            size="normal"
                                            className="justify-center"
                                            locale={locale}
                                            atlas={statusIconAtlas}
                                            characterId={player.characterId}
                                        />
                                    ) : (
                                        <div className="text-slate-500 text-sm text-center">
                                            {t('interaction.noStatus')}
                                        </div>
                                    )}
                                </PlayerCardShell>
                            );
                        })}
                    </div>
                )}

                {/* 转移目标选择（第二阶段） */}
                {isTransferTargetSelection && (
                    <div className="flex flex-wrap gap-4 justify-center">
                        {targetPlayerIds.map(pid => {
                            const player = players[pid];
                            if (!player) return null;

                            const isSourcePlayer = pid === interaction.transferConfig?.sourcePlayerId;
                            const { teamTone, seatLabel, displayName, relationLabel } = getPlayerMeta(pid);
                            const { idleBorderClassName, passiveBorderClassName, titleClassName, badgeClassName } = getToneClasses(teamTone);
                            const isSelected = selectedItems.includes(pid);
                            const canSelect = !isSourcePlayer;

                            return (
                                <PlayerCardShell
                                    key={pid}
                                    testId={isSourcePlayer ? `dt-transfer-source-locked-${pid}` : `dt-transfer-target-${pid}`}
                                    playerId={pid}
                                    teamTone={teamTone}
                                    titleClassName={titleClassName}
                                    badgeClassName={badgeClassName}
                                    displayName={displayName}
                                    relationLabel={isSourcePlayer ? `${relationLabel} / 已选来源` : relationLabel}
                                    seatLabel={seatLabel}
                                    onClick={canSelect ? () => onSelectPlayer(pid) : undefined}
                                    locked={isSourcePlayer}
                                    selected={isSelected}
                                    footer={
                                        isSourcePlayer
                                            ? '已选来源'
                                            : isSelected
                                                ? '已选目标'
                                                : '点击作为接收目标'
                                    }
                                    containerClassName={`
                                        p-4 rounded-xl border-2 transition-all duration-200 min-w-[200px]
                                        ${canSelect ? 'cursor-pointer hover:scale-[1.03]' : 'cursor-not-allowed opacity-75'}
                                        ${isSourcePlayer
                                            ? `${passiveBorderClassName} ring-2 ring-white/10`
                                            : isSelected
                                                ? 'border-amber-400 bg-amber-950/30 ring-2 ring-amber-300/80'
                                                : idleBorderClassName}
                                    `}
                                >
                                    {isSourcePlayer && transferSourceCard ? (
                                        Object.keys(transferSourceCard.effects).length > 0 || Object.keys(transferSourceCard.tokens).length > 0 ? (
                                            <SelectableEffectsContainer
                                                effects={transferSourceCard.effects}
                                                tokens={transferSourceCard.tokens}
                                                highlightAll={false}
                                                selectedId={transferSourceCard.statusId}
                                                getItemTestId={(statusId) => `dt-transfer-source-effect-${statusId}`}
                                                size="normal"
                                                className="justify-center"
                                                locale={locale}
                                                atlas={statusIconAtlas}
                                                characterId={transferSourceCard.characterId}
                                            />
                                        ) : (
                                            <div className="text-sm text-slate-400">
                                                {transferSourceCard.statusId}
                                            </div>
                                        )
                                    ) : (
                                        <div className={`${canSelect ? '' : passiveBorderClassName} rounded-lg`}>
                                            <SelectableEffectsContainer
                                                effects={player.statusEffects ?? {}}
                                                tokens={player.tokens}
                                                highlightAll={false}
                                                size="normal"
                                                className="justify-center"
                                                locale={locale}
                                                atlas={statusIconAtlas}
                                                characterId={player.characterId}
                                            />
                                        </div>
                                    )}
                                </PlayerCardShell>
                            );
                        })}
                    </div>
                )}

            </div>
        </GameModal>
    );
};

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { GameModal } from './components/GameModal';
import { GameButton } from './components/GameButton';
import { getStatusEffectIconNode } from './statusEffects';
import type { StatusAtlases } from './statusEffects';
import { InfoTooltip } from '../../../components/common/overlays/InfoTooltip';
import { resolveI18nList } from './utils';
import { getVisualMetaById } from '../domain/statusEffects';
import { CardPreview } from '../../../components/common/media/CardPreview';
import type { CardPreviewRef } from '../../../core';
import type { HeroState } from '../domain/types';
import { getPortraitStyle } from './assets';
import { Dice2D } from './Dice2D';
import type { ChoiceRequestedEvent } from '../domain/events';

export interface ChoiceOption {
    id: string;
    label: string;
    labelParams?: Record<string, string | number>;
    statusId?: string;
    tokenId?: string;
    customId?: string;
    value?: number;
    disabled?: boolean;
    previewRef?: CardPreviewRef;
    dicePreview?: ChoiceRequestedEvent['payload']['options'][number]['dicePreview'];
    targetPlayerId?: string;
    choiceKind?: 'card' | 'player' | 'status' | 'skip';
    cardId?: string;
    cardSourceZone?: 'hand' | 'deck' | 'discard' | 'preparedSpells';
    candidateStatusId?: string;
}

/** slider 配置（从领域层透传） */
interface SliderConfig {
    /** 确认按钮文案 i18n key，支持 {{count}} 插值 */
    confirmLabelKey: string;
    /** 滑动条下方提示文案 i18n key，支持 {{value}} 插值 */
    hintKey?: string;
    /** 跳过按钮文案 i18n key（可选，默认用 skip option 的 labelKey） */
    skipLabelKey?: string;
}

interface ChoiceData {
    title: string;
    options: ChoiceOption[];
    /**
     * slider 模式配置。存在时渲染滑动条而非按钮列表。
     * 约定：options[0] = 确认选项（value=max），options[last] = 跳过选项（value=0）
     */
    slider?: SliderConfig;
}

function translateRuntimeKey(
    t: (key: string, opts?: Record<string, unknown>) => string,
    key: string,
    opts?: Record<string, unknown>,
): string {
    const runtimeKey = { value: key };
    return t(runtimeKey.value, opts);
}

const translateInterpolatedParam = (
    t: (key: string, opts?: Record<string, unknown>) => string,
    value: string | number,
): string | number => {
    if (typeof value !== 'string') return value;
    const separator = ', ';
    return value.split(separator).map(part => {
        if (!part.startsWith('cards.') && !part.startsWith('characters.')
            && !part.startsWith('tokens.') && !part.startsWith('statusEffects.')) return part;
        return translateRuntimeKey(t, part, { defaultValue: part });
    }).join(separator);
};

export const ChoiceModal = ({
    choice,
    canResolve,
    onResolve,
    onResolveWithValue,
    locale,
    statusIconAtlas,
    players,
    playerNames,
}: {
    choice: ChoiceData | null | undefined;
    canResolve: boolean;
    /** 按钮模式：选择 optionId */
    onResolve: (optionId: string) => void;
    /** slider 模式：选择 optionId + 自定义 mergedValue */
    onResolveWithValue?: (optionId: string, mergedValue: unknown) => void;
    locale?: string;
    statusIconAtlas?: StatusAtlases | null;
    players?: Record<string, HeroState>;
    playerNames?: Record<string, string>;
}) => {
    const { t } = useTranslation('game-dicethrone');
    // 防御性检查：如果 choice 存在但 options 为空，不显示模态框
    const hasValidOptions = choice && choice.options && choice.options.length > 0;
    const isOpen = !!hasValidOptions;
    const isSlider = !!choice?.slider;
    const cardOptions = choice?.options.filter(option => option.previewRef) ?? [];

    // slider 约定：第一个 option = 确认（value=max），最后一个 = 跳过（value=0）
    const confirmOption = isSlider ? choice!.options[0] : undefined;
    const skipOption = isSlider && choice!.options.length > 1 ? choice!.options[choice!.options.length - 1] : undefined;
    const maxValue = confirmOption?.value ?? 1;

    const resolveOptionLabel = (option: Pick<ChoiceOption, 'label' | 'labelParams'>) => {
        if (option.label.startsWith('choices.option-')) {
            const index = Number(option.label.replace('choices.option-', ''));
            if (!Number.isNaN(index)) {
                return t('choices.option', { index: index + 1 });
            }
        }
        const translatedParams = Object.fromEntries(
            Object.entries(option.labelParams ?? {}).map(([key, value]) => [
                key,
                translateInterpolatedParam(t, value),
            ]),
        );
        return translateRuntimeKey(t, option.label, { ...translatedParams, defaultValue: option.label });
    };

    const handleSliderConfirm = (selectedValue: number) => {
        if (!confirmOption || !onResolveWithValue) return;
        const mergedValue = {
            value: selectedValue,
            customId: confirmOption.customId,
            tokenId: confirmOption.tokenId,
        };
        onResolveWithValue(confirmOption.id, mergedValue);
    };

    const handleSliderSkip = () => {
        if (skipOption) {
            onResolve(skipOption.id);
        }
    };

    const skipLabel = choice?.slider?.skipLabelKey
        ? translateRuntimeKey(t, choice.slider.skipLabelKey, { defaultValue: choice.slider.skipLabelKey })
        : skipOption ? resolveOptionLabel(skipOption) : '';

    return (
        <GameModal
            isOpen={isOpen}
            title={t('choices.title')}
            width={cardOptions.length > 2 ? "xl" : cardOptions.length > 0 ? "lg" : "md"}
            closeOnBackdrop={false}
        >
            <div className="flex flex-col gap-6 max-[1023px]:gap-2 w-full items-center">
                {choice && (
                    <p className="text-lg text-slate-200 font-medium">
                        {t(choice.title)}
                    </p>
                )}

                {isSlider && confirmOption ? (
                    maxValue === 1 ? (
                        <div className="flex gap-4">
                            <GameButton
                                onClick={() => handleSliderConfirm(1)}
                                disabled={!canResolve}
                                variant="primary"
                                className="min-w-[140px]"
                                data-option-id={confirmOption.id}
                                data-choice-custom-id={confirmOption.customId}
                            >
                                {t(choice!.slider!.confirmLabelKey, { count: 1 })}
                            </GameButton>
                            {skipOption && (
                                <GameButton
                                    onClick={handleSliderSkip}
                                    disabled={!canResolve}
                                    variant="secondary"
                                    className="min-w-[100px]"
                                    data-option-id={skipOption.id}
                                    data-choice-custom-id={skipOption.customId}
                                >
                                    {skipLabel}
                                </GameButton>
                            )}
                        </div>
                    ) : (
                        <SliderChoice
                            key={choice?.title}
                            min={1}
                            max={maxValue}
                            canResolve={canResolve}
                            onConfirm={handleSliderConfirm}
                            onSkip={skipOption ? handleSliderSkip : undefined}
                            confirmLabelKey={choice!.slider!.confirmLabelKey}
                            hintKey={choice!.slider!.hintKey}
                            skipLabel={skipLabel}
                            confirmOption={confirmOption}
                            locale={locale}
                            statusIconAtlas={statusIconAtlas}
                            t={t}
                        />
                    )
                ) : (
                    (() => {
                        // 将选项分为 token 图标和普通按钮（skip/cancel 等）
                        const tokenOptions = choice?.options.filter(o => o.tokenId) ?? [];
                        const nonTokenOptions = choice?.options.filter(o => !o.tokenId) ?? [];
                        const isTokenChoice = tokenOptions.length > 0;

                        if (isTokenChoice) {
                            // Token 图标模式：渲染可点击的 token 图标 + 底部跳过/取消按钮
                            return (
                                <div className="flex flex-col items-center gap-4 w-full">
                                    <div className="flex gap-6 justify-center">
                                        {tokenOptions.map(option => (
                                            <TokenChoiceIcon
                                                key={option.id}
                                                option={option}
                                                canResolve={canResolve}
                                                onResolve={onResolve}
                                                locale={locale}
                                                statusIconAtlas={statusIconAtlas}
                                                t={t}
                                            />
                                        ))}
                                    </div>
                                    {nonTokenOptions.map(option => (
                                        <GameButton
                                            key={option.id}
                                            onClick={() => onResolve(option.id)}
                                            disabled={!canResolve || option.disabled}
                                            variant="secondary"
                                            className="min-w-[100px]"
                                            data-option-id={option.id}
                                            data-choice-custom-id={option.customId}
                                        >
                                            {resolveOptionLabel(option)}
                                        </GameButton>
                                    ))}
                                </div>
                            );
                        }

                        if (cardOptions.length) {
                            return (
                                <div className="flex flex-col items-center gap-4 w-full">
                                    <div className="flex flex-wrap justify-center gap-4 w-full">
                                        {cardOptions.map(option => (
                                            <button
                                                key={option.id}
                                                type="button"
                                                aria-label={resolveOptionLabel(option)}
                                                disabled={!canResolve || option.disabled}
                                                onClick={() => onResolve(option.id)}
                                                data-option-id={option.id}
                                                data-choice-custom-id={option.customId}
                                                className="w-40 max-w-full min-w-0 rounded-lg focus-visible:outline-amber-400 hover:ring-2 hover:ring-amber-400 disabled:opacity-50"
                                                style={cardOptions.length === 1
                                                    ? { maxWidth: 'min(10rem, calc(var(--runtime-viewport-height, 100vh) * .31))' }
                                                    : undefined}
                                            >
                                                <CardPreview previewRef={option.previewRef} locale={locale}
                                                    alt={resolveOptionLabel(option)}
                                                    className="w-full rounded-lg overflow-hidden"
                                                    style={{ aspectRatio: '669 / 1086' }} />
                                                <span className="block pt-2 max-[1023px]:pt-0 text-sm text-amber-100">{resolveOptionLabel(option)}</span>
                                            </button>
                                        ))}
                                    </div>
                                    {choice?.options.filter(option => !option.previewRef).map(option => (
                                        <GameButton key={option.id} variant="secondary" disabled={!canResolve || option.disabled}
                                            data-option-id={option.id} data-choice-custom-id={option.customId}
                                            onClick={() => onResolve(option.id)}>{resolveOptionLabel(option)}</GameButton>
                                    ))}
                                </div>
                            );
                        }

                        // 默认按钮模式
                        return (
                            <div className="flex flex-wrap gap-4 w-full justify-center">
                                {choice?.options.map(option => {
                                    const target = option.targetPlayerId ? players?.[option.targetPlayerId] : undefined;
                                    const isCancelOption = option.id === '__cancel__';
                                    return (
                                        <GameButton
                                            key={option.id}
                                            onClick={() => onResolve(option.id)}
                                            disabled={!canResolve || option.disabled}
                                            variant={isCancelOption ? 'secondary' : canResolve ? 'primary' : 'secondary'}
                                            className="min-w-[120px] flex-col"
                                            data-option-id={option.id}
                                            data-choice-custom-id={option.customId}
                                        >
                                            {option.dicePreview && (
                                                <span className="flex gap-3 mb-2" data-choice-dice-preview="true">
                                                    {option.dicePreview.dice.map(die => (
                                                        <span key={die.index} className="flex flex-col items-center gap-2">
                                                            <Dice2D value={die.value} characterId={option.dicePreview!.characterId}
                                                                isRolling={false} locale={locale} size="48px" />
                                                            <span className="text-sm">{die.value}</span>
                                                        </span>
                                                    ))}
                                                </span>
                                            )}
                                            {target && (
                                                <span className="mx-auto mb-2 block h-20 w-20 rounded-full border border-amber-400/40"
                                                    data-choice-target-player={option.targetPlayerId}
                                                    style={getPortraitStyle(target.characterId, locale)} />
                                            )}
                                            {resolveOptionLabel(option)}
                                            {option.targetPlayerId && playerNames?.[option.targetPlayerId] && (
                                                <span className="block text-xs text-slate-300">{playerNames[option.targetPlayerId]}</span>
                                            )}
                                        </GameButton>
                                    );
                                })}
                            </div>
                        );
                    })()
                )}
            </div>
        </GameModal>
    );
};

const TokenChoiceIcon = ({
    option,
    canResolve,
    onResolve,
    locale,
    statusIconAtlas,
    t,
}: {
    option: ChoiceOption;
    canResolve: boolean;
    onResolve: (optionId: string) => void;
    locale?: string;
    statusIconAtlas?: StatusAtlases | null;
    t: (key: string, opts?: Record<string, unknown>) => string;
}) => {
    const [isHovered, setIsHovered] = React.useState(false);
    const tokenId = option.tokenId!;
    const meta = getVisualMetaById(tokenId) || { color: 'from-gray-500 to-gray-600' };

    // 检查精灵图是否存在
    let hasSprite = false;
    if (statusIconAtlas && meta.frameId) {
        if (meta.atlasId && statusIconAtlas[meta.atlasId]) {
            hasSprite = Boolean(statusIconAtlas[meta.atlasId].frames[meta.frameId]);
        } else {
            hasSprite = Object.values(statusIconAtlas).some(config => Boolean(config.frames[meta.frameId!]));
        }
    }

    const name = t(`tokens.${tokenId}.name`);
    const description = resolveI18nList(
        t(`tokens.${tokenId}.description`, { returnObjects: true })
    );

    return (
        <button
            type="button"
            aria-label={name}
            disabled={!canResolve}
            className="relative flex flex-col items-center gap-2 border-0 bg-transparent p-0 cursor-pointer disabled:cursor-not-allowed"
            data-option-id={option.id}
            data-choice-custom-id={option.customId}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            onClick={() => onResolve(option.id)}
        >
            <div
                className={`
                    w-16 h-16 rounded-full flex items-center justify-center overflow-hidden
                    ${hasSprite
                        ? 'bg-transparent'
                        : `bg-gradient-to-br ${meta.color ?? 'from-gray-500 to-gray-600'} border border-white/30`}
                    transition-all duration-200
                    ${canResolve ? 'hover:scale-110 hover:ring-2 hover:ring-amber-400 cursor-pointer' : 'opacity-50 cursor-not-allowed'}
                    shadow-lg
                `}
            >
                {getStatusEffectIconNode(meta, locale, 'choice', statusIconAtlas)}
            </div>
            <span className={`text-sm font-medium ${canResolve ? 'text-slate-200' : 'text-slate-500'}`}>
                {name}
            </span>
            <InfoTooltip
                title={name}
                content={description}
                isVisible={isHovered}
                position="bottom"
            />
        </button>
    );
};

/** 通用 slider 选择子组件（state 内置，通过 key 重置） */
const SliderChoice = ({
    min,
    max,
    canResolve,
    onConfirm,
    onSkip,
    confirmLabelKey,
    hintKey,
    skipLabel,
    confirmOption,
    locale,
    statusIconAtlas,
    t,
}: {
    min: number;
    max: number;
    canResolve: boolean;
    onConfirm: (value: number) => void;
    onSkip?: () => void;
    confirmLabelKey: string;
    hintKey?: string;
    skipLabel?: string;
    confirmOption: ChoiceOption;
    locale?: string;
    statusIconAtlas?: StatusAtlases | null;
    t: (key: string, opts?: Record<string, unknown>) => string;
}) => {
    const [value, setValue] = useState(1);
    const meta = (confirmOption.tokenId ? getVisualMetaById(confirmOption.tokenId) : undefined)
        || { color: 'from-slate-500 to-slate-600' };
    const iconNode = getStatusEffectIconNode(meta, locale, 'choice', statusIconAtlas);

    return (
        <div className="flex flex-col gap-5 w-full items-center">
            {/* 当前选择值显示 */}
            <div className="flex items-center gap-3">
                <span className="w-8 h-8 inline-flex items-center justify-center rounded-full overflow-hidden border border-white/30 bg-black/30">
                    {iconNode}
                </span>
                <span className="text-3xl font-bold text-amber-300 tabular-nums min-w-[2ch] text-center">
                    {value}
                </span>
                <span className="text-slate-400 text-sm">/ {max}</span>
            </div>

            {/* 滑动条 */}
            <div className="w-full px-4">
                <input
                    type="range"
                    min={min}
                    max={max}
                    value={value}
                    onChange={(e) => setValue(Number(e.target.value))}
                    disabled={!canResolve}
                    className="w-full h-2 rounded-full appearance-none cursor-pointer
                        bg-slate-700
                        [&::-webkit-slider-thumb]:appearance-none
                        [&::-webkit-slider-thumb]:w-6
                        [&::-webkit-slider-thumb]:h-6
                        [&::-webkit-slider-thumb]:rounded-full
                        [&::-webkit-slider-thumb]:bg-amber-400
                        [&::-webkit-slider-thumb]:border-2
                        [&::-webkit-slider-thumb]:border-amber-600
                        [&::-webkit-slider-thumb]:shadow-lg
                        [&::-webkit-slider-thumb]:cursor-pointer
                        [&::-moz-range-thumb]:w-6
                        [&::-moz-range-thumb]:h-6
                        [&::-moz-range-thumb]:rounded-full
                        [&::-moz-range-thumb]:bg-amber-400
                        [&::-moz-range-thumb]:border-2
                        [&::-moz-range-thumb]:border-amber-600
                        [&::-moz-range-thumb]:cursor-pointer
                        disabled:opacity-50 disabled:cursor-not-allowed"
                    aria-label={t('choices.sliderLabel')}
                />
                <div className="flex justify-between mt-1 text-xs text-slate-500">
                    <span>{min}</span>
                    <span>{max}</span>
                </div>
            </div>

            {/* 提示文案（由领域层配置） */}
            {hintKey && (
                <p className="text-sm text-slate-400">
                    {translateRuntimeKey(t, hintKey, { value, defaultValue: hintKey })}
                </p>
            )}

            {/* 确认/跳过按钮 */}
            <div className="flex gap-4">
                <GameButton
                    onClick={() => onConfirm(value)}
                    disabled={!canResolve}
                    variant="primary"
                    className="min-w-[140px]"
                >
                    {translateRuntimeKey(t, confirmLabelKey, { count: value, defaultValue: confirmLabelKey })}
                </GameButton>
                {onSkip && skipLabel && (
                    <GameButton
                        onClick={onSkip}
                        disabled={!canResolve}
                        variant="secondary"
                        className="min-w-[100px]"
                    >
                        {skipLabel}
                    </GameButton>
                )}
            </div>
        </div>
    );
};

import clsx from 'clsx';
import { motion, type HTMLMotionProps } from 'framer-motion';
import { forwardRef, type ReactNode } from 'react';
import { playSound } from '../../../../lib/audio/useGameAudio';

// Dice Throne 风格按钮
// High contrast, bold, distinct shapes

interface GameButtonProps extends Omit<HTMLMotionProps<"button">, "children"> {
    children?: ReactNode;
    variant?: 'primary' | 'secondary' | 'danger' | 'ghost' | 'glass';
    size?: 'sm' | 'md' | 'lg';
    fullWidth?: boolean;
    icon?: ReactNode;
    /** 默认播放点击音效，传 null 关闭 */
    clickSoundKey?: string | null;
}

export const GameButton = forwardRef<HTMLButtonElement, GameButtonProps>(({
    children,
    className,
    variant = 'primary',
    size = 'md',
    fullWidth = false,
    icon,
    disabled,
    clickSoundKey,
    onClick,
    ...props
}, ref) => {

    const baseEffects = "relative overflow-hidden transition-all duration-200 active:scale-95 disabled:opacity-50 disabled:pointer-events-none disabled:active:scale-100 disabled:grayscale";
    const typography = "font-black uppercase tracking-wider text-center leading-none select-none flex items-center justify-center gap-2";

    // 视觉风格 - 参考 Dice Throne
    // Primary: Amber/Gold gradient (Main Action)
    // Danger: Red gradient (Attack/Cancel)
    // Secondary: Blue/Slate (Info/Neutral)

    const variants = {
        primary: "bg-gradient-to-b from-amber-400 to-amber-600 border border-amber-300 shadow-[0_4px_0_#b45309] active:shadow-none active:translate-y-1 text-white hover:brightness-110",
        danger: "bg-gradient-to-b from-red-500 to-red-700 border border-red-400 shadow-[0_4px_0_#991b1b] active:shadow-none active:translate-y-1 text-white hover:brightness-110",
        secondary: "bg-slate-700 border border-slate-500 shadow-[0_4px_0_#334155] active:shadow-none active:translate-y-1 text-slate-100 hover:bg-slate-600",
        glass: "bg-white/10 backdrop-blur-md border border-white/20 hover:bg-white/20 text-white shadow-sm active:bg-white/5 shadow-black/20",
        ghost: "bg-transparent text-slate-400 hover:text-white hover:bg-white/5 border border-transparent"
    };

    const sizes = {
        sm: "text-xs py-2 px-3 rounded-lg min-h-[32px]",
        md: "text-sm py-3 px-6 rounded-xl min-h-[44px]",
        lg: "text-base py-4 px-8 rounded-xl min-h-[56px]"
    };

    const resolvedClickSoundKey = clickSoundKey === undefined
        ? 'ui.general.khron_studio_rpg_interface_essentials_inventory_dialog_ucs_system_192khz.dialog.dialog_choice.uiclick_dialog_choice_01_krst_none'
        : clickSoundKey;

    const handleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(event);
        if (!disabled && resolvedClickSoundKey) {
            try {
                playSound(resolvedClickSoundKey);
            } catch {
                // 音效失败不应阻断按钮的真实游戏动作。
            }
        }
    };

    return (
        <motion.button
            ref={ref}
            className={clsx(
                baseEffects,
                typography,
                variants[variant],
                sizes[size],
                fullWidth && "w-full",
                className
            )}
            whileHover={{
                scale: disabled ? 1 : 1.01,
                filter: "brightness(1.05)"
            }}
            whileTap={{ scale: disabled ? 1 : 0.98 }}
            disabled={disabled}
            onClick={handleClick}
            {...props}
        >
            {icon && <span className="text-[1.2em]">{icon}</span>}
            {children}
        </motion.button>
    );
});

GameButton.displayName = 'GameButton';

import { AnimatePresence } from 'framer-motion';
import clsx from 'clsx';
import { type ReactNode } from 'react';
