    onClose?: () => void;
    title?: ReactNode;
    children: ReactNode;
    footer?: ReactNode;
    width?: 'sm' | 'md' | 'lg' | 'xl';
    className?: string;
    closeOnBackdrop?: boolean;
    /** 保留弹窗内容交互，但让背景操作当前仍可干预的游戏对象。 */
    allowBackgroundInteraction?: boolean;
}

export const GameModal = ({
    isOpen,
    onClose,
    title,
    children,
    footer,
    width = 'md',
    className,
    closeOnBackdrop = true,
    allowBackgroundInteraction = false,
}: GameModalProps) => {

    const widthClass = {
        sm: 'max-w-sm',
        md: 'max-w-md',
        lg: 'max-w-xl',
        xl: 'max-w-3xl'
    }[width];

    return (
        <AnimatePresence>
            {isOpen && (
                <ModalBase
                    onClose={onClose}
                    closeOnBackdrop={closeOnBackdrop}
                    overlayClassName={allowBackgroundInteraction
                        ? "!bg-black/35 !backdrop-blur-none pointer-events-none"
                        : "!bg-black/85"}
                    contentWrapperClassName={allowBackgroundInteraction ? 'pointer-events-none' : undefined}
                >
                    <div
                        className={clsx(
                            "relative bg-slate-950 border-2 border-amber-500/40 pointer-events-auto",
                            "shadow-[0_0_50px_rgba(0,0,0,0.8)]",
                            "rounded-2xl overflow-hidden flex flex-col w-full mx-4",
                            "max-h-[calc(var(--runtime-viewport-height,100vh)-1rem)] sm:max-h-[calc(var(--runtime-viewport-height,100vh)-2rem)]",
                            // Dynamic background pattern
                            "before:absolute before:inset-0 before:bg-[radial-gradient(circle_at_top,_var(--tw-gradient-stops))] before:from-slate-800/50 before:to-transparent before:pointer-events-none",
