const HAND_CARD_WIDTH_UNITS = 12;
const HAND_CARD_GAP_UNITS = 7;
const HAND_CARD_SIDE_OFFSET_UNITS = HAND_CARD_WIDTH_UNITS / 2;
const HAND_CARD_Y_OFFSET_UNITS = 0.8;
const HAND_CARD_ROTATION_STEP_DEGREES = 5;
const HAND_CARD_ANCHOR_Y_UNITS = 6;
const HAND_CARD_VIEWPORT_BOTTOM_GAP_UNITS = 3;
const HAND_CARD_HOVER_LIFT_UNITS = 3.1;
const HAND_TUTORIAL_FALLBACK_WIDTH_UNITS = 20;
const HAND_TUTORIAL_VISIBLE_HEIGHT_UNITS = 18;
const HAND_CARD_ASPECT_RATIO = 0.61;

const buildHandCardWidthValue = () => buildBoardShellInlineUnitValue(HAND_CARD_WIDTH_UNITS);
const buildHandCardLeftValue = (offset: number) =>
    `calc(50% + ${buildBoardShellInlineUnitValue(offset * HAND_CARD_GAP_UNITS)} - ${buildBoardShellInlineUnitValue(HAND_CARD_SIDE_OFFSET_UNITS)})`;
const readHandCardGapPixels = () => readBoardShellInlineUnitPixelValue() * HAND_CARD_GAP_UNITS;
const readHandCardYOffsetPixels = (offset: number) => Math.abs(offset) * HAND_CARD_Y_OFFSET_UNITS * readBoardShellInlineUnitPixelValue();
const readHandCardHoverLiftPixels = () => readBoardShellInlineUnitPixelValue() * HAND_CARD_HOVER_LIFT_UNITS;

const getHandAnchorYOffsetFromScreenBottom = () =>
    readBoardShellInlineUnitPixelValue() * HAND_CARD_ANCHOR_Y_UNITS * readBoardShellScaleValue();

/** 飞出卡牌信息（成功使用后的动画） */
type CardOffset = {
    x: number;
    y: number;
};

type FlyingOutCard = {
    card: AbilityCard;
    cardKey: string;
    startOffset: CardOffset;
    startIndex: number;
    targetType: 'discard' | 'abilitySlot';
    targetSlotId?: string;
    targetPos: CardOffset;
    targetScale: number;
};

type HandCardEntry = {
    card: AbilityCard;
    key: string;
    index: number;
};

type DragValues = {
    x: MotionValue<number>;
    y: MotionValue<number>;
};

const buildHandCardKey = (cardId: string, sequence: number) => `${cardId}-${sequence}`;
const parseHandCardSequence = (cardKey: string, cardId: string) => {
    const prefix = `${cardId}-`;
    if (!cardKey.startsWith(prefix)) return 0;
    const sequence = Number(cardKey.slice(prefix.length));
    return Number.isFinite(sequence) ? sequence : 0;
};

const buildNextHandEntries = (hand: AbilityCard[], prevEntries: HandCardEntry[]) => {
    const prevQueues = new Map<string, HandCardEntry[]>();
    const sequenceMap = new Map<string, number>();

    prevEntries.forEach((entry) => {
        const queue = prevQueues.get(entry.card.id) ?? [];
        queue.push(entry);
        prevQueues.set(entry.card.id, queue);

        const prevMax = sequenceMap.get(entry.card.id) ?? 0;
        const sequence = parseHandCardSequence(entry.key, entry.card.id);
        if (sequence > prevMax) {
            sequenceMap.set(entry.card.id, sequence);
        }
    });

    return hand.map((card, index) => {
        const queue = prevQueues.get(card.id);
        const reused = queue?.shift();
        if (reused) {
            if (reused.card === card && reused.index === index) {
                return reused;
            }
            return { ...reused, card, index };
        }
        const nextSequence = (sequenceMap.get(card.id) ?? 0) + 1;
        sequenceMap.set(card.id, nextSequence);
        return { card, index, key: buildHandCardKey(card.id, nextSequence) };
    });
};

const syncDragValueMap = (prevMap: Map<string, DragValues>, cardKeys: string[]) => {
    const nextMap = new Map<string, DragValues>();
    cardKeys.forEach((cardKey) => {
        nextMap.set(cardKey, prevMap.get(cardKey) ?? { x: motionValue(0), y: motionValue(0) });
    });
    return nextMap;
};

