                        {affordable ? (
                            <>
                                <stop offset="0%" stopColor="#0d4450" />
                                <stop offset="56%" stopColor="#0b8a88" />
                                <stop offset="100%" stopColor="#29d3d8" />
                            </>
                        ) : (
                            <>
                                <stop offset="0%" stopColor="#3f4754" />
                                <stop offset="56%" stopColor="#667181" />
                                <stop offset="100%" stopColor="#9ba6b6" />
                            </>
                        )}
                    </linearGradient>
                </defs>
                <path
                    d="M13 6H38.5L66 28L38.5 50H13C8 50 4 46 4 41V15C4 10 8 6 13 6Z"
                    fill={`url(#${gradientId})`}
                    stroke={outerStroke}
                    strokeWidth="3.6"
                    strokeLinejoin="round"
                />
                <path
                    d="M15.5 11H36.2L57.5 28L36.2 45H15.5C12.5 45 10 42.5 10 39.5V16.5C10 13.5 12.5 11 15.5 11Z"
                    fill={affordable ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.09)'}
                    stroke={highlightStroke}
                    strokeWidth="1.2"
                    strokeLinejoin="round"
                />
                <path
                    d="M14.8 12.3H36.3L52.8 25.5"
                    fill="none"
                    stroke={topEdgeStroke}
                    strokeWidth="1.7"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                />
            </svg>
            <span
                className="absolute inset-0 flex items-center justify-center font-black leading-none text-white"
                style={{
                    paddingRight: buildBoardShellInlineUnitValue(0.28),
                    fontSize: buildBoardShellInlineUnitValue(1.18),
                    textShadow: affordable
                        ? `0 ${buildBoardShellInlineUnitValue(0.1)} 0 #06242c, 0 0 ${buildBoardShellInlineUnitValue(0.28)} rgba(255,255,255,0.52)`
                        : `0 ${buildBoardShellInlineUnitValue(0.1)} 0 #1f2937, 0 0 ${buildBoardShellInlineUnitValue(0.18)} rgba(255,255,255,0.22)`,
                }}
            >
                {cost}
            </span>
        </div>
    );
};

export const HandArea = ({
    hand,
    locale,
    currentPhase,
    playerCp = 0,
    onPlayCard,
    onSellCard,
    onError,
    canInteract = true,
    canPlayCards = true,
    canSellCards = canPlayCards,
    drawDeckRef,
    discardPileRef,
    undoCardId,
    onSellHintChange,
    onPlayHintChange,
    onSellButtonChange,
    tutorialAllowedCardIds,
    isDiscardMode = false,
    onDiscardCard,
    onMagnifyCard,
    respondableCardIds,
    characterId,
    playerBoardFace,
    disableCardPointerEvents = false,
    playCardOnClick = false,
    isHidden = false,
    preserveCardVisibility = false,
}: {
    hand: AbilityCard[];
    locale?: string;
    currentPhase?: TurnPhase;
    playerCp?: number;
    onPlayCard?: (card: AbilityCard) => boolean | void;
    onSellCard?: (cardId: string) => void;
    onError?: (message: string) => void;
    canInteract?: boolean;
    canPlayCards?: boolean;
    canSellCards?: boolean;
    drawDeckRef?: RefObject<HTMLDivElement | null>;
    discardPileRef?: RefObject<HTMLDivElement | null>;
    undoCardId?: string;
    onSellHintChange?: (show: boolean) => void;
    onPlayHintChange?: (show: boolean) => void;
    onSellButtonChange?: (show: boolean) => void;
    /** Tutorial action focus; other cards remain readable but cannot be played or sold in this step. */
    tutorialAllowedCardIds?: string[];
    /** 弃牌模式：手牌超限时点击卡牌直接弃置 */
    isDiscardMode?: boolean;
    /** 弃牌模式下点击卡牌的回调 */
    onDiscardCard?: (cardId: string) => void;
    onMagnifyCard?: (card: AbilityCard) => void;
    /** 响应窗口中可响应的卡牌 ID 集合（用于高亮） */
    respondableCardIds?: Set<string>;
    characterId?: string;
    playerBoardFace?: HeroState['playerBoardFace'];
    disableCardPointerEvents?: boolean;
    /** 教程等引导模式下，点击手牌直接承接真实出牌动作；普通对局仍点击预览。 */
    playCardOnClick?: boolean;
    isHidden?: boolean;
    /** 牌池选择等交互中，保持手牌完整落在视口内，不用底部裁切换空间。 */
    preserveCardVisibility?: boolean;
}) => {
    const { t } = useTranslation('game-dicethrone');
    const isCoarsePointer = useCoarsePointer();
    const [draggingCardKey, setDraggingCardKey] = React.useState<string | null>(null);
    const screenDragOffsetRef = React.useRef({ x: 0, y: 0 });
    const dragOffsetRef = React.useRef({ x: 0, y: 0 });
    const draggingCardRef = React.useRef<HandCardEntry | null>(null);
    const dragEndHandledRef = React.useRef(false);
    const lastPointerPointRef = React.useRef<PointerPoint | null>(null);
    const [showSellHint, setShowSellHint] = React.useState(false);
    const [returningCardMap, setReturningCardMap] = React.useState<
        Record<string, { version: number; offset: { x: number; y: number }; originalIndex: number }>
    >({});
    const [returningVersionMap, setReturningVersionMap] = React.useState<Record<string, number>>({});
    // 事件驱动的 hover 状态（用 onHoverStart/onHoverEnd 更新，避免 whileHover 的"元素移到鼠标下"误触发）
    const [hoveredCardKey, setHoveredCardKey] = React.useState<string | null>(null);
    // 飞出动画卡牌（成功使用后飞向目标）
    const [flyingOutCard, setFlyingOutCard] = React.useState<FlyingOutCard | null>(null);
    // 弃牌模式下等待飞出的卡牌（点击弃牌时记录，卡牌从手牌移除后触发飞出动画）
    const pendingDiscardRef = React.useRef<{
        cardKey: string;
        card: AbilityCard;
        originalIndex: number;
    } | null>(null);
    // 正在弃牌的 cardKey（用于跳过 exit 动画，避免和飞出动画重叠）
    const [discardingCardKey, setDiscardingCardKey] = React.useState<string | null>(null);
    const pendingPlayRef = React.useRef<{
        cardKey: string;
        card: AbilityCard;
        offset: CardOffset;
        originalIndex: number;
    } | null>(null);
    const pendingPlayTimeoutRef = React.useRef<number | null>(null);
    const handKeysRef = React.useRef<string[]>([]);
    const cardBackImage = React.useMemo(() => buildLocalizedImageSet(ASSETS.CARD_BG, locale), [locale]);
    const handAreaRef = React.useRef<HTMLDivElement>(null);
    // 拖拽后的合成 click 属于同一次手势，不能打开卡牌预览。
    // 若浏览器没有派发 click，则下一次 pointerdown 会清除这个标记。
    const draggedCardClickBlockRef = React.useRef<string | null>(null);
    const {
        clearLongPressState,
        handlePointerDown: handleCardPointerDown,
        handlePointerMove: handleCardPointerMove,
        handlePointerUp: handleCardPointerUp,
        shouldBlockClick: shouldBlockLongPressClick,
    } = useTouchLongPress<string, AbilityCard>({
        enabled: Boolean(onMagnifyCard) && canInteract && !isDiscardMode,
        durationMs: LONG_PRESS_DURATION_MS,
        moveCancelPx: LONG_PRESS_MOVE_CANCEL_PX,
        clickBlockMs: LONG_PRESS_CLICK_BLOCK_MS,
        onLongPress: (_cardKey, card) => {
            onMagnifyCard?.(card);
        },
    });

    const [handEntries, setHandEntries] = React.useState<HandCardEntry[]>(() => buildNextHandEntries(hand, []));

    const updateDragPointerPoint = React.useCallback((event: React.PointerEvent) => {
        lastPointerPointRef.current = { x: event.clientX, y: event.clientY };
    }, []);

    React.useLayoutEffect(() => {
        setHandEntries(prevEntries => buildNextHandEntries(hand, prevEntries));
    }, [hand]);

    const handKeys = React.useMemo(() => handEntries.map(entry => entry.key), [handEntries]);
    const handKeyToCardId = React.useMemo(
        () => new Map(handEntries.map(entry => [entry.key, entry.card.id] as const)),
        [handEntries]
    );
    const handEntryByKey = React.useMemo(
        () => new Map(handEntries.map(entry => [entry.key, entry] as const)),
        [handEntries]
    );
    const [dragValueMap, setDragValueMap] = React.useState<Map<string, DragValues>>(() => new Map());

    React.useLayoutEffect(() => {
        setDragValueMap(prevMap => syncDragValueMap(prevMap, handKeys));
    }, [handKeys]);

    const resetDragValues = React.useCallback((cardKey: string, _source: 'drag' | 'window') => {
        const values = dragValueMap.get(cardKey);
        if (!values) return;
        animate(values.x, 0, { duration: 0.25, ease: 'easeOut' });
        animate(values.y, 0, { duration: 0.25, ease: 'easeOut' });
    }, [dragValueMap]);

    const getDeckOffset = React.useCallback(() => {
        if (!drawDeckRef?.current || !handAreaRef.current) {
            return {
                x: -readBoardShellInlineUnitPixelValue() * 40,
                y: -readBoardShellBlockUnitPixelValue() * 10,
            };
        }
        const deckRect = drawDeckRef.current.getBoundingClientRect();
        const handRect = handAreaRef.current.getBoundingClientRect();
        const deckCenterX = deckRect.left + deckRect.width / 2;
        const deckCenterY = deckRect.top + deckRect.height / 2;
        const handCenterX = handRect.left + handRect.width / 2;
        const handCenterY = handRect.bottom - getHandAnchorYOffsetFromScreenBottom();
        return {
            x: convertScreenPixelsToBoardShellPixels(deckCenterX - handCenterX),
            y: convertScreenPixelsToBoardShellPixels(deckCenterY - handCenterY),
        };
    }, [drawDeckRef]);

    const getDiscardPileOffset = React.useCallback(() => {
        if (!discardPileRef?.current || !handAreaRef.current) {
            return {
                x: readBoardShellInlineUnitPixelValue() * 40,
                y: -readBoardShellBlockUnitPixelValue() * 10,
            };
        }
        const discardRect = discardPileRef.current.getBoundingClientRect();
        const handRect = handAreaRef.current.getBoundingClientRect();
        const discardCenterX = discardRect.left + discardRect.width / 2;
        const discardCenterY = discardRect.top + discardRect.height / 2;
        const handCenterX = handRect.left + handRect.width / 2;
        const handCenterY = handRect.bottom - getHandAnchorYOffsetFromScreenBottom();
        return {
            x: convertScreenPixelsToBoardShellPixels(discardCenterX - handCenterX),
            y: convertScreenPixelsToBoardShellPixels(discardCenterY - handCenterY),
        };
    }, [discardPileRef]);

    // 获取技能槽位置偏移（用于升级卡动画）
    const getAbilitySlotOffset = React.useCallback((slotId: string) => {
        if (!handAreaRef.current) {
            return { x: 0, y: -readBoardShellBlockUnitPixelValue() * 40 };
        }
        const slotEl = document.querySelector(
            `[data-ability-slot-scope="main-board"][data-ability-slot="${slotId}"]`,
        ) as HTMLElement | null;
        if (!slotEl) {
            return { x: 0, y: -readBoardShellBlockUnitPixelValue() * 40 };
        }
        const slotRect = slotEl.getBoundingClientRect();
        const handRect = handAreaRef.current.getBoundingClientRect();
        const slotCenterX = slotRect.left + slotRect.width / 2;
        const slotCenterY = slotRect.top + slotRect.height / 2;
        const handCenterX = handRect.left + handRect.width / 2;
        const handCenterY = handRect.bottom - getHandAnchorYOffsetFromScreenBottom();
        return {
            x: convertScreenPixelsToBoardShellPixels(slotCenterX - handCenterX),
            y: convertScreenPixelsToBoardShellPixels(slotCenterY - handCenterY),
        };
    }, []);

    const createFlyingOutCard = React.useCallback((params: {
        card: AbilityCard;
        cardKey: string;
        startOffset: CardOffset;
        startIndex: number;
        targetType: 'discard' | 'abilitySlot';
        targetSlotId?: string;
    }): FlyingOutCard => {
        const targetPos = params.targetType === 'abilitySlot' && params.targetSlotId
            ? getAbilitySlotOffset(params.targetSlotId)
            : getDiscardPileOffset();

        return {
            ...params,
            targetPos,
            targetScale: params.targetType === 'abilitySlot' ? 0.4 : 0.5,
        };
    }, [getAbilitySlotOffset, getDiscardPileOffset]);

    const [visibleCardKeys, setVisibleCardKeys] = React.useState<Set<string>>(new Set());
    const [flippedCardKeys, setFlippedCardKeys] = React.useState<Set<string>>(new Set());
    const [dealingCardKey, setDealingCardKey] = React.useState<string | null>(null);
    const [dealInitialOffsetMap, setDealInitialOffsetMap] = React.useState<Map<string, CardOffset>>(() => new Map());
    const prevHandKeysRef = React.useRef<string[]>([]);
    const dealTimersRef = React.useRef<number[]>([]);
    const flipTimersRef = React.useRef<number[]>([]);

    const DEAL_INTERVAL = 150;  // 从 300ms 加快一倍
    const FLIP_INTERVAL = 125;  // 从 250ms 加快一倍
    const RETURN_RESET_DELAY = 320;
    const PENDING_PLAY_TIMEOUT = 2000;

    const totalCards = hand.length;
    const centerIndex = (totalCards - 1) / 2;
    const hasRespondableCards = (respondableCardIds?.size ?? 0) > 0;
    const visibleFanBottomOffset = preserveCardVisibility
        ? Math.max(0, ...handEntries.map(({ index }) => {
            const offset = Math.abs(index - centerIndex);
            const angle = offset * HAND_CARD_ROTATION_STEP_DEGREES * Math.PI / 180;
            // 扇形牌面绕中心旋转，完整可见态同时补偿下移与旋转后的底边。
            return offset * HAND_CARD_Y_OFFSET_UNITS
                + HAND_CARD_WIDTH_UNITS / 2 * Math.abs(Math.sin(angle))
                + HAND_CARD_WIDTH_UNITS / HAND_CARD_ASPECT_RATIO / 2 * (Math.abs(Math.cos(angle)) - 1);
        }))
        : 0;
    const handCardBottomOffset = buildBoardShellInlineUnitValue(
        preserveCardVisibility ? visibleFanBottomOffset : (hasRespondableCards ? 0.75 : (isCoarsePointer ? 0 : -2)),
    );

    const clearAnimationTimers = React.useCallback(() => {
        dealTimersRef.current.forEach(timerId => window.clearTimeout(timerId));
        flipTimersRef.current.forEach(timerId => window.clearTimeout(timerId));
        dealTimersRef.current = [];
        flipTimersRef.current = [];
    }, []);

    const clearPendingPlay = React.useCallback(() => {
        pendingPlayRef.current = null;
        if (pendingPlayTimeoutRef.current) {
            window.clearTimeout(pendingPlayTimeoutRef.current);
            pendingPlayTimeoutRef.current = null;
        }
    }, []);

    const beginPendingCardAction = React.useCallback((entry: HandCardEntry, offset: CardOffset, originalIndex: number) => {
        pendingPlayRef.current = { cardKey: entry.key, card: entry.card, offset, originalIndex };
        if (pendingPlayTimeoutRef.current) {
            window.clearTimeout(pendingPlayTimeoutRef.current);
        }
        pendingPlayTimeoutRef.current = window.setTimeout(() => {
            resetDragValues(entry.key, 'drag');
            clearPendingPlay();
        }, PENDING_PLAY_TIMEOUT);
    }, [clearPendingPlay, resetDragValues]);

    const triggerReturn = React.useCallback((cardKey: string, offset: { x: number; y: number }, originalIndex: number) => {
        // 回弹时清除 hover 状态（事件驱动模型下，元素移动不会触发 onHoverStart）
        setHoveredCardKey(prev => prev === cardKey ? null : prev);
        setReturningCardMap(prev => {
            const prevEntry = prev[cardKey];
            const nextVersion = (prevEntry?.version ?? 0) + 1;
            setReturningVersionMap(prevVersions => ({
                ...prevVersions,
                [cardKey]: nextVersion,
            }));
            return {
                ...prev,
                [cardKey]: {
                    version: nextVersion,
                    offset,
                    originalIndex,
                },
            };
        });
        window.setTimeout(() => {
            setReturningCardMap(prev => {
                if (!prev[cardKey]) return prev;
                const next = { ...prev };
                delete next[cardKey];
                return next;
            });
        }, RETURN_RESET_DELAY);
    }, [RETURN_RESET_DELAY]);

    React.useEffect(() => {
        handKeysRef.current = handKeys;

        // 弃牌模式：卡牌从手牌移除后触发飞向弃牌堆动画
        const pendingDiscard = pendingDiscardRef.current;
        if (pendingDiscard && !handKeys.includes(pendingDiscard.cardKey)) {
            const { card, cardKey, originalIndex } = pendingDiscard;
            setFlyingOutCard(createFlyingOutCard({
                card,
                cardKey,
                startOffset: { x: 0, y: 0 },
                startIndex: originalIndex,
                targetType: 'discard',
            }));
            pendingDiscardRef.current = null;
            setDiscardingCardKey(null);
        }

        // 拖拽打出：卡牌成功使用（从手牌移除），触发飞出动画
        const pending = pendingPlayRef.current;
        if (pending && !handKeys.includes(pending.cardKey)) {
            const { card, offset, originalIndex, cardKey } = pending;

            // 判断目标位置：升级卡飞向技能槽，普通卡飞向弃牌堆
            if (card.type === 'upgrade') {
                // 从卡牌效果中提取目标技能 ID
                const replaceAction = card.effects?.find(e => e.action?.type === 'replaceAbility')?.action;
                const targetAbilityId = replaceAction?.type === 'replaceAbility' ? replaceAction.targetAbilityId : undefined;
                const slotId = targetAbilityId
                    ? getAbilitySlotIdForCharacter(characterId, targetAbilityId, playerBoardFace)
                    : null;

                if (slotId) {
                    setFlyingOutCard(createFlyingOutCard({
                        card,
                        cardKey,
                        startOffset: offset,
                        startIndex: originalIndex,
                        targetType: 'abilitySlot',
                        targetSlotId: slotId,
                    }));
                } else {
                    // 找不到技能槽，默认飞向弃牌堆
                    setFlyingOutCard(createFlyingOutCard({
                        card,
                        cardKey,
                        startOffset: offset,
                        startIndex: originalIndex,
                        targetType: 'discard',
                    }));
                }
            } else if (card.type !== 'spell') {
                // 法术进入准备区；普通行动牌飞向弃牌堆。
                setFlyingOutCard(createFlyingOutCard({
                    card,
                    cardKey,
                    startOffset: offset,
                    startIndex: originalIndex,
                    targetType: 'discard',
                }));
            }
            clearPendingPlay();
        }
    }, [characterId, clearPendingPlay, createFlyingOutCard, handKeys, playerBoardFace]);

    // 监听引擎通知：处理卡牌回弹（错误显示由全局 EngineNotificationListener 处理）
    React.useEffect(() => {
        const handler = (event: Event) => {
            const pending = pendingPlayRef.current;
            if (!pending) return;
            const detail = (event as CustomEvent<EngineNotificationDetail>).detail;
            if (!detail?.error) return;

            // 卡牌仍在手牌中则触发回弹动画
            if (!handKeysRef.current.includes(pending.cardKey)) {
                clearPendingPlay();
                return;
            }
            triggerReturn(pending.cardKey, pending.offset, pending.originalIndex);
            resetDragValues(pending.cardKey, 'drag');
            clearPendingPlay();
        };

        window.addEventListener(ENGINE_NOTIFICATION_EVENT, handler as EventListener);
        return () => window.removeEventListener(ENGINE_NOTIFICATION_EVENT, handler as EventListener);
    }, [clearPendingPlay, resetDragValues, triggerReturn]);

    React.useEffect(() => {
        const currentKeys = handKeys;
        const prevKeys = prevHandKeysRef.current;
        const newKeys = currentKeys.filter(key => !prevKeys.includes(key));
        const removedKeys = prevKeys.filter(key => !currentKeys.includes(key));
        const hasDiff = newKeys.length > 0 || removedKeys.length > 0;

        if (!hasDiff) {
            prevHandKeysRef.current = currentKeys;
            return;
        }

        clearAnimationTimers();
        setDealingCardKey(null);
        const retainedKeys = currentKeys.filter(key => prevKeys.includes(key));

        if (removedKeys.length > 0) {
            setVisibleCardKeys(prev => {
                const next = new Set(prev);
                removedKeys.forEach(key => next.delete(key));
                retainedKeys.forEach(key => next.add(key));
                return next;
            });
            setFlippedCardKeys(prev => {
                const next = new Set(prev);
                removedKeys.forEach(key => next.delete(key));
                retainedKeys.forEach(key => next.add(key));
                return next;
            });
            setDealInitialOffsetMap(prev => {
                const next = new Map(prev);
                removedKeys.forEach(key => next.delete(key));
                return next;
            });
        }

        if (newKeys.length > 0) {
            const isUndoCard = (key: string) => handKeyToCardId.get(key) === undoCardId;
            const undoKeys = newKeys.filter(isUndoCard);
            const normalKeys = newKeys.filter(key => !isUndoCard(key));

            setDealInitialOffsetMap(prev => {
                const next = new Map(prev);
                newKeys.forEach((key) => {
                    const entry = handEntryByKey.get(key);
                    if (!entry) return;
                    const offset = entry.index - centerIndex;
                    const originPos = isUndoCard(key) ? getDiscardPileOffset() : getDeckOffset();
                    next.set(key, {
                        x: originPos.x - offset * readHandCardGapPixels(),
                        y: originPos.y - readHandCardYOffsetPixels(offset),
                    });
                });
                return next;
            });

            if (undoKeys.length > 0) {
                setVisibleCardKeys(prev => new Set([...prev, ...undoKeys]));
                setFlippedCardKeys(prev => new Set([...prev, ...undoKeys]));
                undoKeys.forEach(key => {
                    setDealingCardKey(key);
                    const clearTimerId = window.setTimeout(() => {
                        setDealingCardKey(prev => prev === key ? null : prev);
                    }, DEAL_INTERVAL - 50);
                    dealTimersRef.current.push(clearTimerId);
                });
            }

            normalKeys.forEach((key, i) => {
                const dealTimerId = window.setTimeout(() => {
                    setDealingCardKey(key);
                    setVisibleCardKeys(prev => new Set([...prev, key]));
                    const clearTimerId = window.setTimeout(() => {
                        setDealingCardKey(prev => prev === key ? null : prev);
                    }, DEAL_INTERVAL - 50);
                    dealTimersRef.current.push(clearTimerId);
                }, i * DEAL_INTERVAL);
                dealTimersRef.current.push(dealTimerId);
            });

            const dealEndTime = normalKeys.length * DEAL_INTERVAL;
            const sortedNewKeys = [...normalKeys].sort((a, b) => {
                const idxA = currentKeys.indexOf(a);
                const idxB = currentKeys.indexOf(b);
                return idxA - idxB;
            });
            sortedNewKeys.forEach((key, i) => {
                const flipTimerId = window.setTimeout(() => {
                    setFlippedCardKeys(prev => new Set([...prev, key]));
                }, dealEndTime + i * FLIP_INTERVAL);
                flipTimersRef.current.push(flipTimerId);
            });
        }

        prevHandKeysRef.current = currentKeys;
    }, [centerIndex, clearAnimationTimers, getDeckOffset, getDiscardPileOffset, handEntryByKey, handKeyToCardId, handKeys, undoCardId]);

    const isOverDiscardPile = React.useCallback(() => {
        const activeDraggingCardKey = draggingCardKey ?? draggingCardRef.current?.key;
        if (!discardPileRef?.current || !activeDraggingCardKey) return false;
        const discardRect = discardPileRef.current.getBoundingClientRect();
        const draggedEl = document.querySelector(`[data-card-key="${activeDraggingCardKey}"]`) as HTMLElement | null;
        if (!draggedEl) return false;
        const cardRect = draggedEl.getBoundingClientRect();
        return isHandCardReleaseOverDiscardPile(cardRect, discardRect, {
            isCoarsePointer,
            pointerPoint: lastPointerPointRef.current,
        });
    }, [discardPileRef, draggingCardKey, isCoarsePointer]);

    const handleDragEnd = React.useCallback((entry: HandCardEntry, source: 'drag' | 'window' = 'drag') => {
        clearLongPressState(entry.key);
        if (!canInteract) return;
        if (dragEndHandledRef.current && source === 'drag') return;
        dragEndHandledRef.current = true;
        const { x, y } = dragOffsetRef.current;
        const screenOffset = screenDragOffsetRef.current;
        const overDiscard = isOverDiscardPile();
        const currentIndex = handEntries.findIndex(item => item.key === entry.key);
        const offset = { x, y };
        const card = entry.card;
        const releaseIntent = resolveHandDragReleaseIntent({ overDiscard, yOffset: screenOffset.y });

        let actionTaken = false;
        if (releaseIntent === 'sell') {
            if (!canSellCards && onError) {
                onError(t('error.notYourTurn'));
            } else if (onSellCard) {
                beginPendingCardAction(entry, offset, currentIndex);
                onSellCard(card.id);
                actionTaken = true;
            }
        } else if (releaseIntent === 'play' && onPlayCard) {
            // 向上拖拽打出：直接调用引擎，由引擎返回错误
            beginPendingCardAction(entry, offset, currentIndex);
            const playAccepted = onPlayCard(card);
            if (playAccepted === false) {
                clearPendingPlay();
            } else {
                actionTaken = true;
            }
        }

        if (!actionTaken) {
            triggerReturn(entry.key, offset, currentIndex);
            resetDragValues(entry.key, source);
        }
        setDraggingCardKey(null);
        draggingCardRef.current = null;
        lastPointerPointRef.current = null;
        screenDragOffsetRef.current = { x: 0, y: 0 };
        dragOffsetRef.current = { x: 0, y: 0 };
        onPlayHintChange?.(false);
        setShowSellHint(false);
        onSellHintChange?.(false);
        onSellButtonChange?.(false);
    }, [
        canInteract,
        canSellCards,
        beginPendingCardAction,
        clearLongPressState,
        clearPendingPlay,
        handEntries,
        isOverDiscardPile,
        onError,
        onPlayCard,
        onPlayHintChange,
        onSellCard,
        onSellButtonChange,
        onSellHintChange,
        resetDragValues,
        t,
        triggerReturn,
    ]);

    const handleDrag = (cardKey: string, info: { offset: { x: number; y: number } }) => {
        screenDragOffsetRef.current = info.offset;
        const boardShellOffset = {
            x: convertScreenPixelsToBoardShellPixels(info.offset.x),
            y: convertScreenPixelsToBoardShellPixels(info.offset.y),
        };
        dragOffsetRef.current = boardShellOffset;
        const dragValues = dragValueMap.get(cardKey);
        dragValues?.x.set(boardShellOffset.x);
        dragValues?.y.set(boardShellOffset.y);
        const canSellInPhase = canSellCardsInPhase(currentPhase);
        const nextSellHint = canSellInPhase && isOverDiscardPile();
        if (showSellHint !== nextSellHint) {
            setShowSellHint(nextSellHint);
            onSellHintChange?.(nextSellHint);
        }
    };

    const handleCardDragStart = React.useCallback((entry: HandCardEntry, canDrag: boolean, dragValues: DragValues) => {
        if (!canDrag) return;
        clearLongPressState(entry.key);
        draggedCardClickBlockRef.current = entry.key;
        dragEndHandledRef.current = false;
        draggingCardRef.current = entry;
        screenDragOffsetRef.current = { x: 0, y: 0 };
        dragOffsetRef.current = { x: 0, y: 0 };
        dragValues.x.set(0);
        dragValues.y.set(0);
        setDraggingCardKey(entry.key);
        onSellButtonChange?.(true);
        onPlayHintChange?.(true);
    }, [clearLongPressState, onPlayHintChange, onSellButtonChange]);

    const handleCardClick = React.useCallback((entry: HandCardEntry, options: {
        canClickDiscard: boolean;
        canClickPlay: boolean;
        canPreviewCard: boolean;
    }) => {
        const { canClickDiscard, canClickPlay, canPreviewCard } = options;
        if (draggedCardClickBlockRef.current === entry.key) {
            draggedCardClickBlockRef.current = null;
            return;
        }
        if (shouldBlockLongPressClick(entry.key)) return;

        if (canClickDiscard && onDiscardCard) {
            pendingDiscardRef.current = {
                cardKey: entry.key,
                card: entry.card,
                originalIndex: entry.index,
            };
            setDiscardingCardKey(entry.key);
            onDiscardCard(entry.card.id);
            return;
        }

        if (canClickPlay && onPlayCard) {
            const currentIndex = handEntries.findIndex(item => item.key === entry.key);
            beginPendingCardAction(entry, { x: 0, y: 0 }, currentIndex);
            const playAccepted = onPlayCard(entry.card);
            if (playAccepted === false) {
                clearPendingPlay();
            }
            return;
        }

        if (canPreviewCard) {
            onMagnifyCard?.(entry.card);
        }
    }, [
        beginPendingCardAction,
        clearPendingPlay,
        handEntries,
        onDiscardCard,
        onMagnifyCard,
        onPlayCard,
        resetDragValues,
        shouldBlockLongPressClick,
    ]);

    React.useEffect(() => {
        const handlePointerEnd = (event: PointerEvent) => {
            if (!draggingCardRef.current || dragEndHandledRef.current) return;
            lastPointerPointRef.current = { x: event.clientX, y: event.clientY };
            handleDragEnd(draggingCardRef.current, 'window');
        };

        const handleWindowBlur = () => {
            if (!draggingCardRef.current || dragEndHandledRef.current) return;
            handleDragEnd(draggingCardRef.current, 'window');
        };

        window.addEventListener('pointerup', handlePointerEnd);
        window.addEventListener('pointercancel', handlePointerEnd);
        window.addEventListener('blur', handleWindowBlur);
        return () => {
            window.removeEventListener('pointerup', handlePointerEnd);
            window.removeEventListener('pointercancel', handlePointerEnd);
            window.removeEventListener('blur', handleWindowBlur);
        };
    }, [handleDragEnd]);

    // 教程高亮目标：根据手牌数量动态计算卡牌区域宽度，避免全屏宽度的蓝框
    const cardSpreadWidth = totalCards > 0
        ? (totalCards - 1) * HAND_CARD_GAP_UNITS + HAND_CARD_WIDTH_UNITS + 4
        : HAND_TUTORIAL_FALLBACK_WIDTH_UNITS;
    const cardAreaHeight = HAND_TUTORIAL_VISIBLE_HEIGHT_UNITS;
    const handCardWidth = buildHandCardWidthValue();
    const flyingOutMetrics = React.useMemo(() => {
        if (!flyingOutCard) return null;
        const flyingCenterIndex = centerIndex;
        const startIndexOffset = flyingOutCard.startIndex - flyingCenterIndex;
        return {
            card: flyingOutCard.card,
            cardKey: flyingOutCard.cardKey,
            startIndexOffset,
            startOffset: flyingOutCard.startOffset,
            targetPos: flyingOutCard.targetPos,
            targetScale: flyingOutCard.targetScale,
            fadeOutAtTarget: flyingOutCard.targetType === 'abilitySlot',
        };
    }, [centerIndex, flyingOutCard]);

    return (
        <div
            ref={handAreaRef}
            data-testid="hand-area"
            data-hand-hidden={isHidden}
            aria-hidden={isHidden}
            className="absolute bottom-0 left-0 right-0 flex justify-center items-end pb-0 pointer-events-none"
            style={{
                zIndex: UI_Z_INDEX.hud,
                height: buildBoardShellInlineUnitValue(HAND_AREA_HEIGHT_UNITS),
                display: isHidden ? 'none' : undefined,
            }}
        >
            {/* 教程高亮目标：仅覆盖实际卡牌区域 */}
            <div
                data-tutorial-id="hand-area"
                className="absolute bottom-0 left-1/2 pointer-events-none"
                style={{ width: buildBoardShellInlineUnitValue(cardSpreadWidth), height: buildBoardShellInlineUnitValue(cardAreaHeight), transform: 'translateX(-50%)' }}
            />
            <div
                className="relative h-full flex justify-center items-end"
                style={{ width: buildBoardShellInlineUnitValue(95) }}
            >
                <AnimatePresence>
                    {handEntries.map((entry) => {
                        const { card, key: cardKey, index: i } = entry;
                        const isVisible = visibleCardKeys.has(cardKey);
                        if (!isVisible) return null;

                        const offset = i - centerIndex;
                        const rotation = offset * HAND_CARD_ROTATION_STEP_DEGREES;
                        const isDragging = draggingCardKey === cardKey;
                        const isDealing = dealingCardKey === cardKey;
                        const isFlipped = flippedCardKeys.has(cardKey);
                        const returningEntry = returningCardMap[cardKey];
                        const zIndex = isDragging ? UI_Z_INDEX.hud + 40 : UI_Z_INDEX.hud + 1 + i;
                        const isReturning = !!returningEntry;
                        const returnVersion = returningVersionMap[cardKey] ?? 0;
                        const tutorialCardAllowed = !tutorialAllowedCardIds?.length || tutorialAllowedCardIds.includes(card.id);
                        // 弃牌模式下禁用拖拽，改用点击
                        const canDrag = canInteract && isFlipped && !isReturning && !isDiscardMode && tutorialCardAllowed;
                        const canClickDiscard = isDiscardMode && isFlipped && !isReturning && tutorialCardAllowed;
                        const canClickPlay = playCardOnClick && canPlayCards && isFlipped && !isReturning && !isDiscardMode && tutorialCardAllowed;
                        const canPreviewCard = Boolean(onMagnifyCard) && isFlipped && !isReturning && tutorialCardAllowed;
                        const canHoverCard = (canDrag || canClickDiscard || canPreviewCard || respondableCardIds?.has(card.id))
                            && !disableCardPointerEvents;
                        // 动画期间（dealing/returning）统一禁用 hover
                        const isHovered = hoveredCardKey === cardKey && canHoverCard && !isDragging && !isReturning && !isDealing;
                        const dragValues = dragValueMap.get(cardKey);
                        if (!dragValues) return null;
                        const canAffordCard = playerCp >= card.cpCost;
                        // 正在弃牌的卡牌立即消失（飞出动画由 flyingOutCard 接管）
                        const isBeingDiscarded = discardingCardKey === cardKey;
                        const dealInitial = dealInitialOffsetMap.get(cardKey);
                        const motionInitial = isDealing
                            ? (dealInitial ? {
                                opacity: 1,
                                x: dealInitial.x,
                                y: dealInitial.y,
                                scale: 0.5,
                                rotate: 0,
                            } : false)
                            : (returningEntry ? (() => {
                                const origOffset = returningEntry.originalIndex - centerIndex;
                                return {
                                    opacity: 1,
                                    x: (origOffset - offset) * readHandCardGapPixels() + returningEntry.offset.x,
                                    y: (readHandCardYOffsetPixels(origOffset) - readHandCardYOffsetPixels(offset)) + returningEntry.offset.y,
                                    scale: 1,
                                    rotate: 0,
                                };
                            })() : false);

                        return (
                            <motion.div
                                key={`${cardKey}-${returnVersion}`}
                                data-card-key={cardKey}
                                data-card-id={card.id}
                                data-tutorial-id={`hand-card-${card.id}`}
                                data-can-drag={canDrag}
                                data-tutorial-allowed={tutorialCardAllowed}
                                data-is-flipped={isFlipped}
                                data-is-discard-mode={isDiscardMode}
                                drag={canDrag}
                                dragElastic={0.1}
                                dragMomentum={false}
                                onPointerDown={(event) => {
                                    if (draggedCardClickBlockRef.current === cardKey) {
                                        draggedCardClickBlockRef.current = null;
                                    }
                                    updateDragPointerPoint(event);
                                    handleCardPointerDown(event, cardKey, card);
                                }}
                                onPointerMove={(event) => {
                                    updateDragPointerPoint(event);
                                    handleCardPointerMove(event, cardKey);
                                    if (canHoverCard && !isDragging && !isReturning) {
                                        setHoveredCardKey(cardKey);
                                    }
                                }}
                                onPointerUp={(event) => {
                                    updateDragPointerPoint(event);
                                    handleCardPointerUp(cardKey);
                                }}
                                onTouchEnd={(event) => {
                                    // 长按抬手时取消合成点击，避免同一手势立即点中详情背景并关闭它。
                                    if (shouldBlockLongPressClick(cardKey)) event.preventDefault();
                                }}
                                onPointerCancel={(event) => {
                                    updateDragPointerPoint(event);
                                    handleCardPointerUp(cardKey);
                                }}
                                onDragStart={() => handleCardDragStart(entry, canDrag, dragValues)}
                                onDrag={(_, info) => canDrag && handleDrag(cardKey, info)}
                                onDragEnd={() => canDrag && handleDragEnd(entry, 'drag')}
                                onClick={() => handleCardClick(entry, { canClickDiscard, canClickPlay, canPreviewCard })}
                                onHoverStart={() => undefined}
                                onHoverEnd={() => {
                                    setHoveredCardKey(prev => prev === cardKey ? null : prev);
                                }}
                                className={`
                                    absolute bottom-0
                                    ${!tutorialCardAllowed ? 'cursor-default' : (canClickDiscard || canClickPlay ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing')}
                                    ${disableCardPointerEvents ? 'pointer-events-none' : 'pointer-events-auto'}
                                    origin-bottom-center bg-transparent overflow-visible
                                `}
                                style={{
                                    bottom: handCardBottomOffset,
                                    width: handCardWidth,
                                    height: `calc(${handCardWidth} / ${HAND_CARD_ASPECT_RATIO})`,
                                    aspectRatio: `${HAND_CARD_ASPECT_RATIO} / 1`,
                                    left: buildHandCardLeftValue(offset),
                                    borderRadius: buildBoardShellInlineUnitValue(0.8),
                                    opacity: tutorialCardAllowed ? 1 : 0.58,
                                    x: dragValues.x,
                                    y: dragValues.y,
                                    zIndex,
                                }}
                            >
                                <motion.div
                                    data-testid="hand-card-visual"
                                    className="relative w-full h-full"
                                    initial={motionInitial}
                                    animate={{
                                        opacity: 1,
                                        x: 0,
                                        y: isHovered ? -readHandCardHoverLiftPixels() : readHandCardYOffsetPixels(offset),
                                        scale: isDragging ? 1.15 : (isHovered ? 1.2 : 1),
                                        rotate: isDragging || isHovered ? 0 : rotation,
                                    }}
                                    exit={isBeingDiscarded
                                        ? { opacity: 0, scale: 1, transition: { duration: 0 } }
                                        : { opacity: 0, scale: 0.8 }
                                    }
                                    transition={isDragging
                                        ? { duration: 0 }
                                        : {
                                            duration: 0.25,
                                            ease: 'easeOut',
                                        }
                                    }
                                >
                                    <div className="relative w-full h-full" style={{ perspective: '1000px' }}>
                                        <motion.div
                                            className={`
                                                relative w-full h-full shadow-2xl
                                                ${isDragging ? 'ring-4 ring-amber-400 shadow-amber-500/50' : ''}
                                                ${canClickDiscard && isHovered ? 'ring-4 ring-red-500 shadow-red-500/50' : ''}
                                                ${canClickDiscard && !isHovered ? 'ring-2 ring-red-500/50' : ''}
                                                ${respondableCardIds?.has(card.id) && !isDragging && !canClickDiscard ? 'ring-4 ring-cyan-400 shadow-cyan-400/60' : ''}
                                            `}
                                            style={{
                                                transformStyle: 'preserve-3d',
                                                WebkitTransformStyle: 'preserve-3d',
                                                willChange: 'transform',
                                                borderRadius: buildBoardShellInlineUnitValue(0.8),
                                            }}
                                            initial={{ rotateY: isFlipped ? 0 : 180 }}
                                            animate={{ rotateY: isFlipped ? 0 : 180 }}
                                            transition={{ duration: 0.6 }}
                                        >
                                            <div
                                                data-card-face="front"
                                                className="absolute inset-0 w-full h-full overflow-visible"
                                                style={{
                                                    transform: 'translateZ(0.1px)',
                                                    WebkitTransform: 'translateZ(0.1px)',
                                                    backfaceVisibility: 'hidden',
                                                    WebkitBackfaceVisibility: 'hidden',
                                                    borderRadius: buildBoardShellInlineUnitValue(0.8),
                                                }}
                                            >
                                                <CardPreview
                                                    previewRef={card.previewRef}
                                                    locale={locale}
                                                    className="w-full h-full border border-slate-700"
                                                    style={{
                                                        backgroundColor: '#1e293b',
                                                        borderRadius: buildBoardShellInlineUnitValue(0.8),
                                                    }}
                                                />
                                                {card.type !== 'spell' && (
                                                    <HandCardCostBadge cost={card.cpCost} affordable={canAffordCard} />
                                                )}
                                            </div>
                                            <div
                                                data-card-face="back"
                                                className="absolute inset-0 w-full h-full border border-slate-700"
                                                style={{
                                                    transform: 'rotateY(180deg) translateZ(0.1px)',
                                                    WebkitTransform: 'rotateY(180deg) translateZ(0.1px)',
                                                    backgroundImage: cardBackImage,
                                                    backgroundSize: 'cover',
                                                    backfaceVisibility: 'hidden',
                                                    WebkitBackfaceVisibility: 'hidden',
                                                    borderRadius: buildBoardShellInlineUnitValue(0.8),
                                                }}
                                            />
                                        </motion.div>
                                    </div>
                                </motion.div>
                            </motion.div>
                        );
                    })}
                </AnimatePresence>

                {/* 飞出动画卡牌（成功使用后飞向目标） */}
                <AnimatePresence>
                    {flyingOutMetrics ? (
                        <motion.div
                            key={`flying-${flyingOutMetrics.cardKey}`}
                            data-testid="hand-flying-card"
                            className="absolute bottom-0 pointer-events-none"
                            style={{
                                bottom: handCardBottomOffset,
                                width: handCardWidth,
                                height: `calc(${handCardWidth} / ${HAND_CARD_ASPECT_RATIO})`,
                                aspectRatio: `${HAND_CARD_ASPECT_RATIO} / 1`,
                                left: buildHandCardLeftValue(flyingOutMetrics.startIndexOffset),
                                borderRadius: buildBoardShellInlineUnitValue(0.8),
                                zIndex: UI_Z_INDEX.overlayRaised,
                            }}
                            initial={{
                                x: flyingOutMetrics.startOffset.x,
                                y: flyingOutMetrics.startOffset.y + readHandCardYOffsetPixels(flyingOutMetrics.startIndexOffset),
                                scale: 1,
                                opacity: 1,
                            }}
                            animate={{
                                x: flyingOutMetrics.targetPos.x - flyingOutMetrics.startIndexOffset * readHandCardGapPixels(),
                                y: flyingOutMetrics.targetPos.y - readHandCardYOffsetPixels(flyingOutMetrics.startIndexOffset),
                                scale: flyingOutMetrics.targetScale,
                                opacity: flyingOutMetrics.fadeOutAtTarget ? 0 : 1,
                            }}
                            exit={{ opacity: 0 }}
                            transition={{ duration: 0.35, ease: 'easeInOut' }}
                            onAnimationComplete={() => setFlyingOutCard(null)}
                        >
                            <CardPreview
                                previewRef={flyingOutMetrics.card.previewRef}
                                locale={locale}
                                className="w-full h-full border border-slate-700 shadow-2xl"
                                style={{
                                    backgroundColor: '#1e293b',
                                    borderRadius: buildBoardShellInlineUnitValue(0.8),
                                }}
                            />
                        </motion.div>
                    ) : null}
                </AnimatePresence>
            </div>
        </div>
    );
};

/**
 * BoardOverlays 组件
 * 
 * 统一管理所有弹窗和覆盖层，简化主组件结构
 */

import React from 'react';
import { useTranslation } from 'react-i18next';
import { AnimatePresence } from 'framer-motion';
import { CardPreview } from '../../../components/common/media/CardPreview';
import { OptimizedImage } from '../../../components/common/media/OptimizedImage';
import { MagnifyOverlay } from '../../../components/common/overlays/MagnifyOverlay';
import { CardSpotlightOverlay } from './CardSpotlightOverlay';
import { AbilityOverlays } from './AbilityOverlays';
import { EndgameOverlay } from '../../../components/game/framework/widgets/EndgameOverlay';
import { RematchActions } from '../../../components/game/framework/widgets/RematchActions';
import { DiceThroneEndgameContent, renderDiceThroneButton } from './DiceThroneEndgame';
import type { StatusAtlases } from './statusEffects';
import type { AbilityCard, HeroState, CharacterId, TurnPhase } from '../domain/types';
import type { PlayerId } from '../../../engine/types';
import type { CardSpotlightItem } from './CardSpotlightOverlay';
import {
    getPlayerBoardAspectRatio,
} from './abilitySlotLayout';
import { getPendingBonusSettlementDice } from '../domain/rules';
import { useHorizontalDragScroll } from '../../../hooks/ui/useHorizontalDragScroll';
import { createScopedLogger } from '../../../lib/logger';

const boardOverlaysLogger = createScopedLogger('DT_BOARD_OVERLAYS');

export interface BoardOverlaysProps {
    // 放大预览
    isMagnifyOpen: boolean;
    /** 交互提示期间的阅读层级；未传时使用通用放大层级。 */
    magnifyZIndex?: number;
    magnifiedImage: string | null;
    magnifiedCard: AbilityCard | null;
    magnifiedCards: AbilityCard[];
    onCloseMagnify: () => void;
    availableAbilityIds: string[];
    canSelectAbility: boolean;
    canHighlightAbility: boolean;
    onSelectAbility: (abilityId: string) => void;
    onHighlightedAbilityClick?: () => void;
    selectedAbilityId?: string;
    activatingAbilityId?: string;
    /** 当前视角玩家的技能等级（用于放大预览叠加升级卡） */
    abilityLevels?: Record<string, number>;
    /** 当前视角玩家的角色 ID */
    viewCharacterId?: string;
    /** 当前视角玩家的面板朝向 */
    viewPlayerBoardFace?: HeroState['playerBoardFace'];

    players: Record<PlayerId, HeroState>;
    currentPlayerId: PlayerId;
    playerNames: Record<PlayerId, string>;
    seatingOrder?: PlayerId[];
    teamIdByPlayerId?: Record<PlayerId, string>;

    // 卡牌特写
    cardSpotlightQueue: CardSpotlightItem[];
    onCardSpotlightClose: (id: string) => void;
    opponentHeaderRef: React.RefObject<HTMLDivElement | null>;


    // 游戏结束
    isGameOver: boolean;
    gameoverResult: any;
    playerID?: string;
    reset?: () => void;
    rematchState: any;
    onRematchVote: () => void;

    // 其他
    statusIconAtlas?: StatusAtlases | null;
    locale: string;
    currentPhase: TurnPhase;

    // 选角相关
    selectedCharacters: Record<PlayerId, CharacterId>;
    hostPlayerId: PlayerId;

    /** 教程模式下特写强制自动关闭延迟（毫秒） */
    tutorialSpotlightAutoCloseDelayMs?: number;
}

export const BoardOverlays: React.FC<BoardOverlaysProps> = (props) => {
    const { t } = useTranslation('game-dicethrone');
    const { ref: multiCardScrollRef, dragProps: multiCardDragProps } = useHorizontalDragScroll();
    const isPlayerBoardPreview = Boolean(props.magnifiedImage?.includes('player-board'));
    const isMultiCardPreview = props.magnifiedCards.length > 0;
    const playerBoardAspectRatio = getPlayerBoardAspectRatio(props.viewCharacterId);
    const playerBoardPreviewWidth = `min(90vw, calc(90vh * ${playerBoardAspectRatio}))`;
    const magnifiedCardWidth = 'min(54.9vh, 39.65vw, 396px, 60vw, 400px)';
    const magnifiedMultiCardWidth = 'min(28vw, 350px, calc(54.9vh - 2.44vw))';
    const shouldRenderMagnifiedAbilityOverlay = isPlayerBoardPreview && Boolean(props.viewCharacterId);
    const magnifyContainerClassName = `
        group/modal
        ${isPlayerBoardPreview ? 'h-auto w-auto max-h-[90vh] max-w-[90vw]' : ''}
        ${props.magnifiedCard ? 'w-auto max-h-[90vh] max-w-[60vw]' : ''}
        ${isMultiCardPreview ? 'max-h-[90vh] max-w-[90vw]' : ''}
        ${!isPlayerBoardPreview && !props.magnifiedCard && !isMultiCardPreview ? 'max-h-[90vh] max-w-[90vw]' : ''}
    `;
    const handleSelectMagnifiedAbility = React.useCallback((abilityId: string) => {
        props.onSelectAbility(abilityId);
        props.onCloseMagnify();
    }, [props.onCloseMagnify, props.onSelectAbility]);

    return (
        <>
            <AnimatePresence>
                {/* 放大预览 */}
                {props.isMagnifyOpen && (
                    <MagnifyOverlay
                        key="magnify"
                        isOpen={props.isMagnifyOpen}
                        onClose={props.onCloseMagnify}
                        zIndex={props.magnifyZIndex}
                        containerClassName={magnifyContainerClassName}
                        closeLabel={t('actions.closePreview')}
                        overlayTestId="board-magnify-overlay"
                    >
                        {isMultiCardPreview ? (
                            <div
                                ref={multiCardScrollRef}
                                {...multiCardDragProps}
                                data-testid="dt-multi-card-magnify-strip"
                                className="flex flex-nowrap items-center justify-start gap-[2vw] p-[2vw] overflow-x-auto overflow-y-hidden"
                                style={multiCardDragProps.style}
                            >
                                {props.magnifiedCards.map((card) => (
                                    <CardPreview
                                        key={card.id}
                                        className="rounded-xl shadow-2xl border border-white/20 flex-shrink-0"
                                        style={{
                                            backgroundColor: '#0f172a',
                                            width: magnifiedMultiCardWidth,
                                            height: `calc(${magnifiedMultiCardWidth} / 0.61)`,
                                            aspectRatio: '0.61 / 1',
                                        }}
                                        previewRef={card.previewRef}
                                        locale={props.locale}
                                    />
                                ))}
                            </div>
                        ) : props.magnifiedCard ? (
                            <CardPreview
                                className="rounded-[1vw]"
                                style={{
                                    backgroundColor: '#0f172a',
                                    width: magnifiedCardWidth,
                                    height: `calc(${magnifiedCardWidth} / 0.61)`,
                                    aspectRatio: '0.61 / 1',
                                }}
                                previewRef={props.magnifiedCard.previewRef}
                                locale={props.locale}
                            />
                        ) : (
                            <div
                                className="relative"
                                style={isPlayerBoardPreview
                                    ? {
                                        width: playerBoardPreviewWidth,
                                        height: `calc(${playerBoardPreviewWidth} / ${playerBoardAspectRatio})`,
                                        aspectRatio: String(playerBoardAspectRatio),
                                    }
                                    : undefined}
                            >
                                <OptimizedImage
                                    src={props.magnifiedImage ?? ''}
                                    locale={props.locale}
                                    className={isPlayerBoardPreview
                                        ? 'block w-full h-full object-contain'
                                        : 'block max-h-[90vh] max-w-[90vw] w-auto h-auto object-contain'}
                                    alt={t('imageAlt.magnifiedView')}
                                />
                                {/* 玩家面板放大时复用原技能槽命中层，保证放大态仍可直接选技能 */}
                                {shouldRenderMagnifiedAbilityOverlay && props.viewCharacterId && (
                                    <AbilityOverlays
                                        isEditing={false}
                                        availableAbilityIds={props.availableAbilityIds}
                                        canSelect={props.canSelectAbility}
                                        canHighlight={props.canHighlightAbility}
                                        onSelectAbility={handleSelectMagnifiedAbility}
                                        onHighlightedAbilityClick={props.onHighlightedAbilityClick}
                                        selectedAbilityId={props.selectedAbilityId}
                                        activatingAbilityId={props.activatingAbilityId}
                                        abilityLevels={props.abilityLevels}
                                        characterId={props.viewCharacterId}
                                        playerBoardFace={props.viewPlayerBoardFace}
                                        locale={props.locale}
                                        slotScope="magnified-preview"
                                    />
                                )}
                            </div>
                        )}
                    </MagnifyOverlay>
                )}

                {/* 卡牌特写 */}
                {props.cardSpotlightQueue.length > 0 && (
                    <CardSpotlightOverlay
                        key="card-spotlight"
                        queue={props.cardSpotlightQueue}
                        locale={props.locale}
                        onClose={props.onCardSpotlightClose}
                        opponentHeaderRef={props.opponentHeaderRef}
                        autoCloseDelay={props.tutorialSpotlightAutoCloseDelayMs}
                    />
                )}
            </AnimatePresence>

            {/* 游戏结束覆盖层 - 注入王权骰铸专属终局胜负内容和重赛按钮样式 */}
            <EndgameOverlay
                isGameOver={props.isGameOver}
                result={props.gameoverResult}
                playerID={props.playerID}
                reset={props.reset}
                isMultiplayer={true}
                totalPlayers={Object.keys(props.players).length}
                rematchState={props.rematchState}
                onVote={props.onRematchVote}
                backdropClassName="bg-transparent"
                contentWrapperClassName="max-[1023px]:max-w-[30rem]"
                scrollMode="content"
                renderContent={(contentProps) => (
                    <DiceThroneEndgameContent
                        {...contentProps}
                        players={props.players}
                        myPlayerId={props.playerID ?? null}
                        locale={props.locale}
                    />
                )}
                renderActions={(actionsProps) => (
                    <RematchActions
                        {...actionsProps}
                        className="mt-4 flex-wrap justify-center"
                        renderButton={renderDiceThroneButton}
                    />
                )}
            />
        </>
    );
};

/**
 * 多技能选择弹窗
 *
 * 当进攻阶段确认骰面后，多个不同 slot 的技能同时满足条件时弹出，
 * 让玩家明确选择要发动哪个技能。
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { GameModal } from './components/GameModal';
import { GameButton } from './components/GameButton';

export interface AbilityChoiceOption {
    /** 要 dispatch 的 abilityId（变体 ID 或基础 ID） */
    abilityId: string;
    /** 技能名称 i18n key（如 abilities.kidney-shot-2.name） */
    name: string;
    /** 技能描述 i18n key */
    description?: string;
    /** 所属 slot ID（用于去重） */
    slotId: string;
}

interface AbilityChoiceModalProps {
    isOpen: boolean;
    options: AbilityChoiceOption[];
    onSelect: (abilityId: string) => void;
    onSkip: () => void;
}

export const AbilityChoiceModal: React.FC<AbilityChoiceModalProps> = ({
    isOpen,
    options,
    onSelect,
    onSkip,
}) => {
    const { t } = useTranslation('game-dicethrone');

    return (
        <GameModal
            isOpen={isOpen}
            title={t('abilityChoice.title')}
            width="md"
            closeOnBackdrop={false}
        >
            <p className="text-sm text-slate-400 mb-4">
                {t('abilityChoice.description')}
            </p>
            <div className="flex flex-col gap-2">
                {options.map((opt) => (
                    <button
                        key={opt.abilityId}
                        className="w-full text-left px-4 py-3 rounded-xl border border-amber-500/30
                            bg-slate-800/80 hover:bg-amber-500/20 hover:border-amber-400/60
                            transition-all duration-150 cursor-pointer group"
                        onClick={() => onSelect(opt.abilityId)}
                    >
                        <div className="font-bold text-amber-300 group-hover:text-amber-200 text-base">
                            {opt.name}
                        </div>
                        {opt.description && (
                            <div className="text-xs text-slate-400 group-hover:text-slate-300 mt-1 line-clamp-2">
                                {opt.description}
                            </div>
                        )}
                    </button>
                ))}
            </div>
            <div className="mt-4 flex justify-end">
                <GameButton
                    variant="ghost"
                    size="sm"
                    onClick={onSkip}
                >
                    {t('abilityChoice.skip')}
                </GameButton>
            </div>
        </GameModal>
    );
};

/**
 * 卡牌特写队列组件
 *
 * 用于展示其他玩家打出的卡牌，支持队列显示。
 * 无遮罩、无虚化背景。
 *
 * 若该卡牌触发了额外骰子投掷，可在右侧同时展示骰子动画。
 */

import React from 'react';
import { CardPreview } from '../../../components/common/media/CardPreview';
import type { CardPreviewRef } from '../../../core';
import { UI_Z_INDEX } from '../../../core';
import SpotlightContainer from './SpotlightContainer';

const SPOTLIGHT_CARD_WIDTH = '16vw';
const SPOTLIGHT_CARD_ASPECT_RATIO = 0.61;

/** 特写队列项 */
export interface CardSpotlightItem {
    /** 唯一标识（通常用 cardId + timestamp） */
    id: string;
    /** 卡牌 ID（用于可测试地确认当前特写展示的是哪张卡） */
    cardId?: string;
    /** 该卡牌打出的时间戳（用于关联额外骰子） */
    timestamp: number;
    /** 卡牌预览引用 */
    previewRef?: CardPreviewRef;
    /** 打出卡牌的玩家 ID */
    playerId: string;
    /** 打出卡牌的玩家名称 */
    playerName?: string;
    /** 若该卡牌触发了额外骰子，附带骰子信息（支持多颗骰子） */
    bonusDice?: Array<{
        index?: number;
        value: number;
        face?: DieFace;
        timestamp: number;
        presentationKey?: string | number;
        presentationKind?: 'roll' | 'choice';
        effectKey?: string;
        effectParams?: Record<string, string | number>;
        /** 骰子所属角色（用于图集选择） */
        characterId?: string;
    }>;
    /** 汇总文本（如"2个弓面：伤害+2"，或奖励骰转交右侧骰盘时的首次结果说明） */
    summaryText?: {
        effectKey: string;
        effectParams: Record<string, string | number>;
    };
}

const getCardIdFromSpotlightItem = (item: CardSpotlightItem): string => {
    if (item.cardId) {
        return item.cardId;
    }
    const suffix = `-${item.timestamp}`;
    return item.id.endsWith(suffix) ? item.id.slice(0, -suffix.length) : item.id;
};

interface CardSpotlightOverlayProps {
    /** 特写队列 */
    queue: CardSpotlightItem[];
    /** 语言 */
    locale?: string;
    /** 当前项关闭回调（从队列中移除） */
    onClose: (id: string) => void;
    /** 对手悬浮窗元素引用（用于计算起始位置） */
    opponentHeaderRef?: React.RefObject<HTMLElement | null>;
    /** 自动关闭延迟（毫秒），默认 3 秒 */
    autoCloseDelay?: number;
}

export const CardSpotlightOverlay: React.FC<CardSpotlightOverlayProps> = ({
    queue,
    locale,
    onClose,
    opponentHeaderRef,
    autoCloseDelay = 3000,
}) => {
    const currentItem = queue[0];
    const currentItemId = currentItem?.id;

    // NOTE: eslint (react-hooks/refs) forbids reading refs during render.
    // We compute the fly-in start position in a layout effect and only render once it's ready for the current item.
    const [startPos, setStartPos] = React.useState<{ x: number; y: number }>({ x: 0, y: 0 });
    const [startPosForId, setStartPosForId] = React.useState<string | null>(null);

    React.useLayoutEffect(() => {
        if (!currentItemId) {
            setStartPosForId(null);
            return;
        }

        let pos = { x: 0, y: -window.innerHeight * 0.3 };
        if (opponentHeaderRef?.current) {
            const rect = opponentHeaderRef.current.getBoundingClientRect();
            pos = {
                x: rect.left + rect.width / 2 - window.innerWidth / 2,
                y: rect.top + rect.height / 2 - window.innerHeight / 2,
            };
        }

        setStartPos(pos);
        setStartPosForId(currentItemId);
    }, [currentItemId, opponentHeaderRef]);

    if (!currentItem || startPosForId !== currentItemId) {
        return null;
    }
    const currentCardId = getCardIdFromSpotlightItem(currentItem);


    return (
        <SpotlightContainer
            id={currentItem.id}
            isVisible={true}
            onClose={() => onClose(currentItem.id)}
            autoCloseDelay={autoCloseDelay}
            zIndex={UI_Z_INDEX.overlayRaised}
            closeOnContentClick={false}
            allowContentPointerEvents={true}
            contentMotion={{
                initial: { x: startPos.x, y: startPos.y, scale: 0.2, opacity: 0 },
                animate: { x: 0, y: '-10vh', scale: 1, opacity: 1 },
                exit: { scale: 0.8, opacity: 0 },
                transition: { type: 'spring', stiffness: 200, damping: 25 },
            }}
        >
            <div
                data-testid="card-spotlight-overlay"
                data-card-id={currentCardId}
                data-player-id={String(currentItem.playerId)}
                data-spotlight-item-id={currentItem.id}
            >
                {/* 卡牌（左） */}
                <CardPreview
                    previewRef={currentItem.previewRef}
                    locale={locale}
                    className="rounded-[0.6vw] shadow-2xl border-2 border-amber-500/60"
                    style={{
                        width: SPOTLIGHT_CARD_WIDTH,
                        height: `calc(${SPOTLIGHT_CARD_WIDTH} / ${SPOTLIGHT_CARD_ASPECT_RATIO})`,
                        aspectRatio: `${SPOTLIGHT_CARD_ASPECT_RATIO} / 1`,
                        boxShadow: '0 0 1.5vw 0.3vw rgba(251, 191, 36, 0.4)',
                    }}
                />
            </div>


            {/* 队列指示器 */}
            {queue.length > 1 && (
                <div className="absolute bottom-[-2vw] flex items-center gap-[0.4vw]">
                    {queue.map((item, index) => (
                        <div
                            key={item.id}
                            className={`w-[0.5vw] h-[0.5vw] rounded-full transition-colors ${index === 0 ? 'bg-amber-400' : 'bg-slate-500'
                                }`}
                        />
                    ))}
                </div>
            )}
        </SpotlightContainer>
    );
};

export default CardSpotlightOverlay;
